Object.assign(window.TEM8_DICTIONARY, {"rapid":{"media":{"uk":"media/uk/rapid__gb_1.mp3","us":"media/us/rapid__us_1.mp3"},"oxford":{"phon":"ˈræpɪd","pos":"adjective","senses":[{"en":"happening quickly or in a short period of time","cn":"瞬间的；快速的","ex":{"en":"rapid change/expansion/growth/development","cn":"迅速的改变／扩张／增长／发展"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快速的；迅速的","en":"A rapid change is one that happens very quickly.","ex":{"en":"...the country's rapid economic growth in the 1980's","cn":"20世纪80年代该国经济的迅速增长"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动作）很快的，迅速进行的","en":"A rapid movement is one that is very fast.","ex":{"en":"He walked at a rapid pace along Charles Street.","cn":"他快步走过查尔斯大街。"}}]},"examples":[{"en":"The disease is spreading with alarming rapidity.","cn":"这种疾病正在以令人吃惊的速度蔓延。"},{"en":"The disease is spreading at a rapid rate.","cn":"这种疾病正在迅速蔓延。"}]},"rarity":{"media":{"uk":"media/uk/rarity__gb_1.mp3","us":"media/us/rarity__us_1.mp3"},"oxford":{"phon":"ˈreərəti","pos":"noun","senses":[{"en":"a person or thing that is unusual and is therefore often valuable or interesting","cn":"珍品；稀有物","g":"[countable]","ex":{"en":"Women are still something of a rarity in senior positions in business.","cn":"在商界位居高职的女性仍然十分罕见。"}},{"en":"the quality of being rare","cn":"稀有；罕见","g":"[uncountable]","lab":"less frequent","ex":{"en":"The value of antiques will depend on their condition and rarity.","cn":"古董的价值依它们的保存状况和稀有程度而定。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"罕见的人（或物）；奇物;珍品","en":"If someone or something is a rarity, they are interesting or valuable because they are so unusual.","ex":{"en":"Motorized wheelchairs are a rarity here","cn":"电动轮椅在这里很罕见。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"稀有;罕见","en":"The rarity of something is the fact that it is very uncommon.","ex":{"en":"This indicates the rarity of such attacks","cn":"这显示出这种疾病发作的罕见性。"}}]},"examples":[{"en":"The value of antiques will depend on their condition and rarity.","cn":"古董的价值依它们的保存状况和稀有程度而定。"},{"en":"Women are still something of a rarity in senior positions in business.","cn":"在商界位居高职的女性仍然十分罕见。"}]},"rabbit":{"oxford":{"phon":"ˈræbɪt","pos":"noun","senses":[{"en":"a small animal with soft fur, long ears and a short tail. Rabbits live in holes in the ground or are kept as pets or for food.","cn":"兔","g":"[countable]","ex":{"en":"a rabbit hutch","cn":"兔笼"}},{"en":"meat from a rabbit","cn":"兔肉","g":"[uncountable]"},{"en":"to hunt or shoot rabbits","cn":"猎兔；捕兔","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兔;野兔","en":"A rabbit is a small furry animal with long ears. Rabbits are sometimes kept as pets, or live wild in holes in the ground.","ex":{"en":"...rabbit stew.","cn":"焖兔肉"}},{"pos":"","cn":"","en":"相关词组：rabbit on"}]},"media":{"img":["media/ldoce/img/rabbit.jpg","media/pic/rabbit_hare.jpg"],"uk":"media/uk/rabbit__gb_1.mp3","us":"media/us/rabbit__us_1.mp3"},"examples":[{"en":"a rabbit hutch","cn":"兔笼"},{"en":"He kept rabbiting on about the environment.","cn":"他没完没了地唠叨环境问题。"}]},"radioactive":{"oxford":{"phon":"ˌreɪdiəʊˈæktɪv","pos":"adjective","senses":[{"en":"sending out powerful and very dangerous rays when the nuclei (= central parts) of atoms are broken up","cn":"放射性的；有辐射的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"放射性的;有辐射的","en":"Something that is radioactive contains a substance that produces energy in the form of powerful and harmful rays.","ex":{"en":"The government has been storing radioactive waste at Fernald for 50 years.","cn":"政府在弗纳德存放放射性废料已达50年之久。"}}]},"media":{"uk":"media/uk/radioactive__gb_1.mp3","us":"media/us/radioactive__us_1.mp3"},"examples":[{"en":"a rise in the level of radioactivity","cn":"辐射强度的增加"},{"en":"the study of radioactivity","cn":"放射性研究"}]},"raise":{"media":{"uk":"media/uk/raise__gb_1.mp3","us":"media/us/raise__us_1.mp3"},"oxford":{"phon":"reɪz","pos":"verb","senses":[{"en":"to lift or move something to a higher level","cn":"提升；举起；提起","lab":"British English","sc":"move upwards","ex":{"en":"She raised the gun and fired.","cn":"她举枪射击。"}},{"en":"to move somebody/something/yourself to a standing, sitting or vertical position","cn":"（使）直立，站立","sc":"move upwards","ex":{"en":"Somehow we managed to raise her to her feet.","cn":"不管怎样，我们终于让她站了起来。"}},{"en":"to increase the amount or level of something","cn":"增加，提高（数量、水平等）","sc":"increase","ex":{"en":"to raise prices/taxes","cn":"涨价；增税"}},{"en":"to bring or collect money or people together; to manage to get or form something","cn":"筹募；征集；召集；组建","sc":"collect money/people","ex":{"en":"We are raising money for charity.","cn":"我们在进行慈善募捐。"}},{"en":"to mention something for people to discuss or somebody to deal with","cn":"提及；提起（课题）","sc":"mention subject","ex":{"en":"The book raises many important questions.","cn":"这本书谈到了许多重要问题。"}},{"en":"to cause or produce a feeling or reaction","cn":"引起，产生（感觉或反应）","sc":"cause/produce","ex":{"en":"to raise doubts in people’s minds","cn":"引起人们的怀疑"}},{"en":"to make something happen or appear","cn":"使产生；使出现","sc":"cause/produce","ex":{"en":"She raised the alarm when he failed to return home.","cn":"他没有回家，这引起了她的警觉。"}},{"en":"to care for a child or young animal until it is able to take care of itself","cn":"抚养；养育；培养","lab":"especially North American English","sc":"child/animal","ex":{"en":"She raised five children on her own.","cn":"她独自抚养了五个孩子。"}},{"en":"to breed (= keep and produce young from) particular farm animals; to grow particular crops","cn":"饲养；培育；种植","sc":"farm animals/crops","ex":{"en":"Farmers cleared the land in order to raise cattle.","cn":"农民清理出土地来养牛。"}},{"en":"to end the limits on somebody/something","cn":"终止，解除（限制）","sc":"end something","ex":{"en":"to raise a blockade/ban/siege","cn":"解除封锁／禁令／包围"}},{"en":"to contact somebody and speak to them by radio or phone","cn":"（通过无线电或电话）与…取得联系，和…通话","sc":"on radio/phone","ex":{"en":"We managed to raise him on his mobile phone.","cn":"我们打他的移动电话，总算找到了他。"}},{"en":"to make somebody who has died come to life again","cn":"使起死回生；使复活","sc":"dead person","ex":{"en":"Christians believe that God raised Jesus from the dead.","cn":"基督徒相信上帝使耶稣复活。"}},{"en":"to make a higher bet than another player in a card game","cn":"在（另一玩牌人）基础上加注","sc":"in card games","ex":{"en":"I'll raise you another hundred dollars.","cn":"我比你再加 100 美元。"}},{"en":"to multiply an amount by itself a particular number of times","cn":"使自乘（若干次）","sc":"mathematics","ex":{"en":"3 raised to the power of 3 is 27 (= 3 × 3 × 3).","cn":"3 的三次方等于 27。"}},{"en":"to build something","cn":"建立；建造","lab":"especially North American English","sc":"build","ex":{"en":"Our priority will be to raise a boundary wall and prevent trespassing.","cn":"我们的首要任务是修建边界墙，防止非法侵入。"}},{"en":"to create a document such as an invoice or a petition","cn":"升／降温；增加／减少热烈程度等","sc":"document","ex":{"en":"They have been raising a petition against the war.","cn":"他们一直在提出反对战争的请愿书。"}},{"en":"an increase in the money you are paid for the work you do","cn":"加薪；工资增长","ex":{"en":"If I asked my boss for a raise he’d fire me.","cn":"我要是要求老板加薪，他会解雇我。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"举起；抬高","en":"If you raise something, you move it so that it is in a higher position.","ex":{"en":"He raised his hand to wave","cn":"他举手挥动起来。"}},{"pos":"VERB 动词","cn":"升起，举起（旗帜）","en":"If you raise a flag, you display it by moving it up a pole or into a high place where it can be seen.","ex":{"en":"They had raised the white flag in surrender","cn":"他们举白旗投降了。"}},{"pos":"VERB 动词","cn":"起身；站立","en":"If you raise yourself, you lift your body so that you are standing up straight, or so that you are no longer lying flat.","ex":{"en":"He raised himself into a sitting position","cn":"他坐了起来。"}},{"pos":"VERB 动词","cn":"增加；提高","en":"If you raise the rate or level of something, you increase it.","ex":{"en":"The Republic of Ireland is expected to raise interest rates","cn":"爱尔兰共和国预计会提高利率。"}},{"pos":"VERB 动词","cn":"提高（水平）；改善","en":"To raise the standard of something means to improve it.","ex":{"en":"...a new drive to raise standards of literacy in Britain's schools.","cn":"提高英国学校文化水平的新运动"}},{"pos":"VERB 动词","cn":"（常指因发怒而）提高（嗓门）","en":"If you raise your voice, you speak more loudly, usually because you are angry.","ex":{"en":"Don't you raise your voice to me, Henry Rollins!","cn":"别冲我叫嚷，亨利·罗林斯！"}},{"pos":"N-COUNT 可数名词","cn":"加薪；提薪","en":"A raise is an increase in your wages or salary.","ex":{"en":"Within two months Kelly got a raise.","cn":"不到两个月，凯利就获得了加薪。"}},{"pos":"VERB 动词","cn":"（为慈善组织、机构等）募捐，筹（款）","en":"If you raise money for a charity or an institution, you ask people for money which you collect on its behalf.","ex":{"en":"...events held to raise money for Help the Aged","cn":"为“帮助老年人”活动而发起的募捐活动"}},{"pos":"VERB 动词","cn":"筹集，筹措（资金）","en":"If a person or company raises money that they need, they manage to get it, for example by selling their property or by borrowing.","ex":{"en":"They raised the money to buy the house and two hundred acres of grounds.","cn":"他们筹钱来购买房屋及200英亩的土地。"}},{"pos":"VERB 动词","cn":"引起;唤起;激起","en":"If an event raises a particular emotion or question, it makes people feel the emotion or consider the question.","ex":{"en":"The agreement has raised hopes that the war may end soon","cn":"那项协议使人们感到战争有望很快结束。"}},{"pos":"VERB 动词","cn":"提起，提出（问题、反对等）","en":"If you raise a subject, an objection, or a question, you mention it or bring it to someone's attention.","ex":{"en":"In the meeting Mrs. Ashrawi raised the three main concerns that the Palestinians had","cn":"会议上，阿什拉维夫人提出了巴勒斯坦人最为关注的三个问题。"}},{"pos":"VERB 动词","cn":"养育；抚养","en":"Someone who raises a child looks after it until it is grown up.","ex":{"en":"My mother was an amazing woman. She raised four of us kids virtually singlehandedly.","cn":"我的母亲是位了不起的女性。她几乎是一个人把我们4个孩子带大的。"}},{"pos":"VERB 动词","cn":"饲养；种植","en":"If someone raises a particular type of animal or crop, they breed that type of animal or grow that type of crop.","ex":{"en":"He raises 2,000 acres of wheat and hay.","cn":"他种植了2,000英亩的小麦和牧草。"}},{"pos":"","cn":"","en":"to raise the alarm→see: ; to raise your eyebrows→see: ; to raise a finger→see: ; to raise hell→see: ; to raise a laugh→see: ; to raise the roof→see: ;"}]},"examples":[{"en":"It wasn't an easy audience but he raised a laugh with his joke.","cn":"虽然这些观众很难逗乐，但他的笑话还是引起了一阵笑声。"},{"en":"Don't tell her about the job until you know for sure — we don't want to raise her hopes (= make her hope too much).","cn":"没确定之前别告诉她工作的事，我们不想让她期望过高。"}]},"rapidly":{"oxford":{"phon":"ˈræpɪdli","pos":"adverb","senses":[{"en":"very quickly; at a great rate","cn":"迅速地；快速地","ex":{"en":"to increase/spread/expand rapidly","cn":"快速增加／蔓延／扩展"}}]},"media":{"uk":"media/uk/rapidly__gb_1.mp3","us":"media/us/rapidly__us_1.mp3"},"examples":[{"en":"Crime figures are rising rapidly.","cn":"犯罪数字正在迅速上升。"},{"en":"a rapidly growing economy","cn":"迅速增长的经济"}]},"raw":{"media":{"uk":"media/uk/raw__gb_1.mp3","us":"media/us/raw__us_1.mp3"},"oxford":{"phon":"rɔː","pos":"adjective","senses":[{"en":"not cooked","cn":"生的；未烹制的；未煮的","sc":"food","ex":{"en":"raw meat","cn":"生肉"}},{"en":"in its natural state; not yet changed, used or made into something else","cn":"未经加工的；自然状态的","g":"[usually before noun]","sc":"materials","ex":{"en":"raw sewage","cn":"未经处理的污水"}},{"en":"not yet organized into a form in which it can be easily used or understood","cn":"未经处理的；未经分析的；原始的","g":"[usually before noun]","sc":"information","ex":{"en":"This information is only raw data and will need further analysis.","cn":"这些资料只是原始数据，还需要进一步分析。"}},{"en":"powerful and natural; not trained or showing control","cn":"粗犷的；未经训练的","g":"[usually before noun]","sc":"emotions/qualities","ex":{"en":"songs full of raw emotion","cn":"充满豪放情感的歌曲"}},{"en":"red and painful because the skin has been damaged","cn":"红肿疼痛的；皮肤破损的；擦伤的","sc":"part of body","ex":{"en":"There were raw patches on her feet where the shoes had rubbed.","cn":"她的双脚被鞋子磨破了好几块皮。"}},{"en":"new to a job or an activity and therefore without experience or skill","cn":"工作生疏的；不熟练的；无经验的","g":"[usually before noun]","sc":"person","ex":{"en":"a raw beginner","cn":"没有经验的新手"}},{"en":"very cold","cn":"寒冷的；严寒的","sc":"weather","ex":{"en":"a raw north wind","cn":"寒冷的北风"}},{"en":"honest, direct and sometimes shocking","cn":"真实的；反映真实情况的","lab":"North American English","sc":"description","ex":{"en":"a raw portrayal of working-class life","cn":"工人阶级生活的真实写照"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经加工的;天然状态的","en":"Raw materials or substances are in their natural state before being processed or used in manufacturing.","ex":{"en":"We import raw materials and energy and export mainly industrial products.","cn":"我们进口原材料和能源，主要出口工业产品。"}},{"pos":"ADJ 形容词","cn":"（食物）生的，生食的，未熟的","en":"Raw food is food that is eaten uncooked, that has not yet been cooked, or that has not been cooked enough.","ex":{"en":"...a popular dish made of raw fish","cn":"受欢迎的生鱼菜肴"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"露肉的;擦破皮的","en":"If a part of your body is raw, it is red and painful, perhaps because the skin has come off or has been burnt.","ex":{"en":"...the drag of the rope against the raw flesh of my shoulders","cn":"绳子摩擦着我蹭破了皮的肩头"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情感）不加掩饰的，原始的，朴实的","en":"Raw emotions are strong basic feelings or responses which are not weakened by other influences.","ex":{"en":"...the raw passions of nationalism","cn":"朴实的民族主义热情"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简单的;强大的;真实的","en":"If you describe something as raw, you mean that it is simple, powerful, and real.","ex":{"en":"...the raw power of instinct.","cn":"本能的强大力量"}},{"pos":"ADJ 形容词","cn":"（信息）未经处理的，原始的","en":"Raw data is facts or information that has not yet been sorted, analysed, or prepared for use.","ex":{"en":"Analyses were conducted on the raw data.","cn":"对原始数据进行了分析。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有经验的;不熟练的","en":"If you describe someone in a new job as raw, or as a raw recruit, you mean that they lack experience in that job.","ex":{"en":"...replacing experienced men with raw recruits","cn":"用新手替代有经验的人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）生冷的，阴冷的","en":"Raw weather feels unpleasantly cold.","ex":{"en":"Once they cleared the housetops, the wind was raw and biting.","cn":"他们清扫完屋顶后，寒风刺骨。"}},{"pos":"ADJ 形容词","cn":"（污水）未经处理的","en":"Raw sewage is sewage that has not been treated to make it cleaner.","ex":{"en":"...contamination of bathing water by raw sewage.","cn":"洗澡用水被未经处理的污水污染"}},{"pos":"PHRASE 短语","cn":"不公平待遇","en":"If you say that you are getting a raw deal, you mean that you are being treated unfairly.","ex":{"en":"They feel that Quebec is getting a raw deal","cn":"他们觉得魁北克省受到了不公平的待遇。"}},{"pos":"PHRASE 短语","cn":"未开化的；原生态的；处于蒙昧状态的；原原本本的","en":"You use in the raw to describe something that is in its true state, and has not been made civilized or respectable.","ex":{"en":"This is nature in the raw","cn":"这是自然的原生态。"}},{"pos":"","cn":"","en":"to touch a raw nerve→see: ;"}]},"examples":[{"en":"He spent a couple of months on the streets to experience life in the raw.","cn":"他花了几个月时间走街串巷，体验真实的生活。"},{"en":"This information is only raw data and will need further analysis.","cn":"这些资料只是原始数据，还需要进一步分析。"}]},"ran":{"lemma":"run","media":{"uk":"media/uk/ran__gb_1.mp3","us":"media/us/ran__us_1.mp3"}},"racking":{"lemma":"rack"},"ravages":{"media":{"uk":"media/uk/ravages__gb_1.mp3","us":"media/us/ravages__us_1.mp3"},"oxford":{"phon":"ˈrævɪdʒɪz","pos":"noun","senses":[{"en":"the destruction caused by something","cn":"破坏；损害；毁坏","ex":{"en":"the ravages of war","cn":"战争造成的灾难"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"破坏；蹂躏；毁坏","en":"The ravages of time, war, or the weather are the damaging effects that they have.","ex":{"en":"Carol Drinkwater is blessed with a fine bone structure that stands up better to the ravages of time.","cn":"卡罗尔·德林克沃特生就一副好身板，经过岁月历练还那么硬朗。"}}]},"examples":[{"en":"Her looks had not survived the ravages of time.","cn":"她的容颜未能幸免于岁月的摧残。"},{"en":"the ravages of war","cn":"战争造成的灾难"}]},"railway":{"media":{"uk":"media/uk/railway__gb_1.mp3","us":"media/us/railway__us_1.mp3"},"oxford":{"phon":"ˈreɪlweɪ","pos":"noun","senses":[{"en":"a track with rails on which trains run","cn":"铁路；铁道","lab":"British English also","ex":{"en":"The railway is still under construction.","cn":"这条铁路仍在建设之中。"}},{"en":"a system of tracks, together with the trains that run on them, and the organization and people needed to operate them","cn":"铁路系统；铁路公司；铁道部门","ex":{"en":"Her father worked on the railways.","cn":"她父亲在铁路部门工作。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"铁路;铁道","en":"A railway is a route between two places along which trains travel on steel rails.","ex":{"en":"The road ran beside a railway.","cn":"公路建在铁路旁边。"}},{"pos":"N-COUNT 可数名词","cn":"铁路公司;铁路部门","en":"A railway is a company or organization that operates railway routes.","ex":{"en":"...the state-owned French railway.","cn":"法国国有铁路公司"}},{"pos":"N-COUNT 可数名词","cn":"铁路系统；铁路网","en":"A railway is the system and network of tracks that trains travel on."}]},"examples":[{"en":"The railway is still under construction.","cn":"这条铁路仍在建设之中。"},{"en":"Her father worked on the railways.","cn":"她父亲在铁路部门工作。"}]},"racket":{"oxford":{"phon":"ˈrækɪt","pos":"noun","senses":[{"en":"a loud unpleasant noise","cn":"喧哗；吵闹","g":"[singular]","lab":"informal","ex":{"en":"Stop making that terrible racket!","cn":"别吵啦！"}},{"en":"a dishonest or illegal way of getting money","cn":"诈骗；勒索","g":"[countable]","lab":"informal","ex":{"en":"a protection/extortion/drugs, etc. racket","cn":"收取保护费、敲诈、贩毒等勾当"}},{"en":"a piece of sports equipment used for hitting the ball, etc. in the games of tennis, squash or badminton. It has an oval frame, with strings stretched across and down it.","cn":"（网球、壁球、羽毛球等的）球拍","g":"[countable]","ex":{"en":"He smashed his racket into the clay","cn":"他把球拍摔到红土场地上。"}},{"en":"a game for two or four people, similar to squash, played with rackets and a small hard ball in a court with four walls","cn":"墙网球","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"喧嚷；吵闹声","en":"A racket is a loud unpleasant noise.","ex":{"en":"He makes such a racket I'm afraid he disturbs the neighbours","cn":"他如此大声喧闹，我怕他打扰了邻居。"}},{"pos":"N-COUNT 可数名词","cn":"非法的赚钱勾当","en":"You can refer to an illegal activity used to make money as a racket .","ex":{"en":"A smuggling racket is killing thousands of exotic birds each year.","cn":"走私活动每年都会导致数千只珍奇鸟类死亡。"}},{"pos":"N-COUNT 可数名词","cn":"（网球、壁球、羽毛球等用的）球拍","en":"A racket is an oval-shaped bat with strings across it. Rackets are used in tennis, squash, and badminton.","ex":{"en":"Tennis rackets and balls are provided.","cn":"提供网球拍及网球。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"硬球壁球","en":"Rackets is a game which is similar to squash but which is played with a hard ball."}]},"media":{"uk":"media/uk/racket__gb_1.mp3","us":"media/us/racket__us_1.mp3","img":["media/ldoce/img/racket.jpg"]},"examples":[{"en":"Stop making that terrible racket!","cn":"别吵啦！"},{"en":"a protection/extortion/drugs, etc. racket","cn":"收取保护费、敲诈、贩毒等勾当"}]},"radiator":{"media":{"uk":"media/uk/radiator__gb_1.mp3","us":"media/us/radiator__us_1.mp3"},"oxford":{"phon":"ˈreɪdieɪtə(r)","pos":"noun","senses":[{"en":"a hollow metal device for heating rooms. Radiators are usually connected by pipes through which hot water is sent.","cn":"散热器；暖气片","ex":{"en":"a central heating system with a radiator in each room","cn":"每个房间都配有一个散热器的中央供暖系统"}},{"en":"a device for cooling the engine of a vehicle or an aircraft","cn":"（车辆或飞行发动机的）冷却器，水箱","ex":{"en":"He filled his car radiator with water.","cn":"他给汽车散热器加满水。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"散热器;暖气装置","en":"A radiator is a hollow metal device, usually connected by pipes to a central heating system, that is used to heat a room."},{"pos":"N-COUNT 可数名词","cn":"（汽车等的）水箱，冷却器，散热器","en":"The radiator in a car is the part of the engine which is filled with water in order to cool the engine."}]},"examples":[{"en":"a central heating system with a radiator in each room","cn":"每个房间都配有一个散热器的中央供暖系统"}]},"racially":{"oxford":{"phon":"ˈreɪʃəli","pos":"adverb","senses":[{"en":"in a way that is based on or connected with a person's race","cn":"在种族上","ex":{"en":"The attacks were not racially motivated.","cn":"袭击事件不是由种族原因引起的。"}}]},"media":{"uk":"media/uk/racially__gb_1.mp3","us":"media/us/racially__us_1.mp3"},"examples":[{"en":"The attacks were not racially motivated.","cn":"袭击事件不是由种族原因引起的。"},{"en":"racially mixed schools","cn":"不分种族的学校"}]},"races":{"lemma":"race"},"rate":{"media":{"uk":"media/uk/rate__gb_1.mp3","us":"media/us/rate__us_1.mp3"},"oxford":{"phon":"reɪt","pos":"noun","senses":[{"en":"a measurement of the speed at which something happens","cn":"速度；进度","g":"[countable]","ex":{"en":"Figures published today show another fall in the rate of inflation.","cn":"今天公布的数字表明通货膨胀速度又一次下降。"}},{"en":"a measurement of the number of times something happens or something does something during a particular period","cn":"比率；率","g":"[countable]","ex":{"en":"We have seen a reduction in the crime rate over the last 12 months.","cn":"在过去 12 个月里，犯罪率有所下降。"}},{"en":"a fixed amount of money that is charged or paid for something","cn":"价格；费用","g":"[countable]","ex":{"en":"advertising/insurance/postal rates","cn":"广告／保险／邮寄费"}},{"en":"a tax paid by businesses to a local authority for land and buildings that they use","cn":"（地方政府征收的）商业房地产税","g":"[plural]"},{"en":"to have or think that somebody/something has a particular level of quality, value, etc.","cn":"评估；评价；估价","g":"[transitive, intransitive]","ex":{"en":"The university is highly rated for its research.","cn":"这所大学因其研究工作而受到高度评价。"},"pos":"verb"},{"en":"to think that somebody/something is good","cn":"认为…是好的；看好","g":"[transitive]","lab":"informal","ex":{"en":"What did you think of the movie? I didn't rate it myself.","cn":"你觉得这部电影怎么样？我个人认为不怎么样。"},"pos":"verb"},{"en":"to place somebody/something in a particular position on a scale in relation to similar people or things","cn":"划分等级；分等","g":"[transitive, usually passive]","ex":{"en":"The schools were rated according to their exam results.","cn":"这些学校是按考试成绩排名次的。"},"pos":"verb"},{"en":"to be good, important, etc. enough to be treated in a particular way","cn":"值得，配得上（某种对待）","g":"[transitive]","ex":{"en":"The incident didn't even rate a mention in the press.","cn":"这件事在报纸上连提都不值得一提。"},"pos":"verb"},{"en":"to state that a film or video is suitable for a particular audience","cn":"给（电影或录像片）分级","g":"[transitive, usually passive]","ex":{"en":"The cartoon was rated PG.","cn":"这部动画片被评为 PG 级（在家长引导下观看）。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"速度；速率","en":"The rate at which something happens is the speed with which it happens.","ex":{"en":"The rate at which hair grows can be agonisingly slow","cn":"头发生长的速度可能极其缓慢。"}},{"pos":"N-COUNT 可数名词","cn":"比率;频率","en":"The rate at which something happens is the number of times it happens over a period of time.","ex":{"en":"New diet books appear at a rate of nearly one a week","cn":"新的饮食类书籍差不多一周出一本。"}},{"pos":"N-COUNT 可数名词","cn":"价格;费用","en":"A rate is the amount of money that is charged for goods or services.","ex":{"en":"Calls cost 36p per minute cheap rate and 48p at all other times.","cn":"优惠时段的话费是每分钟36便士，其他时段是48便士。"}},{"pos":"N-COUNT 可数名词","cn":"税率；利率","en":"The rate of taxation or interest is the amount of tax or interest that needs to be paid. It is expressed as a percentage of the amount that is earned, gained as profit, or borrowed.","ex":{"en":"The government insisted that it would not be panicked into interest rate cuts.","cn":"政府坚称不会陷入恐慌而匆忙降息。"}},{"pos":"N-PLURAL 复数名词","cn":"（英国）地方税，不动产税，房地产税","en":"In Britain, the rates were a local tax which you paid if you owned property or if you rented property without furniture.","ex":{"en":"Soldiers were exempt from paying rates","cn":"士兵免缴地方税。"}},{"pos":"V-ERG 及物/不及物动词","cn":"评价;评级;评定","en":"If you rate someone or something as good or bad, you consider them to be good or bad. You can also say that someone or something rates as good or bad.","ex":{"en":"Of all the men in the survey, they rate themselves the least fun-loving and the most responsible","cn":"在所有参加调查的人中，他们认为自己最不贪玩、最负责任。"}},{"pos":"VERB 动词","cn":"看好；瞧得上","en":"If you rate someone or something, you think that they are good.","ex":{"en":"It's flattering to know that other clubs have shown interest and seem to rate me","cn":"得知其他俱乐部对我感兴趣并看好我令我受宠若惊。"}},{"pos":"V-PASSIVE 被动动词","cn":"把…评为;把…认定为;把…列为","en":"If someone or something is rated at a particular position or rank, they are calculated or considered to be in that position on a list.","ex":{"en":"He is generally rated Italy's No. 3 industrialist","cn":"他被公认为意大利第三大实业家。"}},{"pos":"VERB 动词","cn":"值得;应该得到","en":"If you say that someone or something rates a particular reaction, you mean that this is the reaction you consider to be appropriate.","ex":{"en":"This is so extraordinary, it rates a medal and a phone call from the President","cn":"这简直不可思议，应该得到一枚奖章以及总统的电话祝贺。"}},{"pos":"PHRASE 短语","cn":"至少","en":"You use at any rate to indicate that what you have just said might be incorrect or unclear in some way, and that you are now being more precise.","ex":{"en":"She modestly suggests that 'sex, or at any rate gender, may account for the difference'","cn":"她谨慎地提出“性别，至少是男女的性征，也许能解释这个差异”。"}},{"pos":"PHRASE 短语","cn":"不管怎样，无论如何（表示现在所说的话更为重要、而非之前所言）","en":"You use at any rate to indicate that the important thing is what you are saying now, and not what was said before.","ex":{"en":"At any rate, Pankin said that relations between the two nations will be restored before the conference","cn":"不管怎样，潘金说两国之间的关系将在会谈之前恢复。"}},{"pos":"PHRASE 短语","cn":"这样下去；长此以往；如此一来","en":"If you say that at this rate something bad or extreme will happen, you mean that it will happen if things continue to develop as they have been doing.","ex":{"en":"At this rate, she would be almost seven feet tall by then","cn":"这样下去，她到时将有7英尺高了。"}}]},"examples":[{"en":"I may be away on business next week but at any rate I'll be back by Friday.","cn":"我下周可能要出差，但无论如何，我最晚星期五回来。"},{"en":"There were maybe 60 or 70 people there. At any rate, the room was packed.","cn":"那里也许有六七十人吧。反正屋子里挤得严严实实。"}]},"race":{"oxford":{"phon":"reɪs","pos":"noun","senses":[{"en":"a competition between people, animals, vehicles, etc. to see which one is the faster or fastest","cn":"赛跑；速度竞赛","g":"[countable]","sc":"competition","ex":{"en":"a boat/horse race","cn":"划船比赛；赛马"}},{"en":"a situation in which a number of people, groups, organizations, etc. are competing, especially for political power or to achieve something first","cn":"竞争；角逐","g":"[singular]","sc":"competition","ex":{"en":"Who will win the race for the White House?","cn":"谁将赢得大选入主白宫？"}},{"en":"a series of horse races that happen at one place on a particular day","cn":"赛马会","g":"[plural]","sc":"for horses","ex":{"en":"to go to the races","cn":"去参加赛马会"}},{"en":"one of the main groups that humans can be divided into according to their physical differences, for example the colour of their skin; the fact of belonging to one of these groups","cn":"人种；种族","g":"[countable, uncountable]","lab":"British English","sc":"people","ex":{"en":"This custom is found in people of all races throughout the world.","cn":"这一习俗在全世界各种族中都有。"}},{"en":"a group of people who share the same language, history, culture, etc.","cn":"民族","g":"[countable]","sc":"people","ex":{"en":"the Nordic races","cn":"北欧日耳曼民族"}},{"en":"a breed or type of animal or plant","cn":"种；属；类；族","g":"[countable]","sc":"animals/plants","ex":{"en":"a race of cattle","cn":"一种牛"}},{"en":"to compete against somebody/something to see who can go faster or the fastest, do something first, etc.; to take part in a race or races","cn":"（和…）比赛；参加比赛","g":"[intransitive, transitive]","sc":"compete","ex":{"en":"They raced to a thrilling victory in the relay.","cn":"他们在接力赛中取得了激动人心的胜利。"},"pos":"verb"},{"en":"to make an animal or a vehicle compete in a race","cn":"使比赛；让…参加速度比赛","g":"[transitive]","sc":"compete","ex":{"en":"to race dogs/horses/pigeons","cn":"赛狗；赛马；赛鸽"},"pos":"verb"},{"en":"to move very fast; to move somebody/something very fast","cn":"（使）快速移动，快速运转","g":"[intransitive, transitive]","sc":"move fast","ex":{"en":"He raced up the stairs.","cn":"他飞快地冲上楼去。"},"pos":"verb"},{"en":"to function very quickly because you are afraid, excited, etc.","cn":"（因为害怕、兴奋等）急速跳动，快速转动","g":"[intransitive]","sc":"of heart/mind/thoughts","ex":{"en":"My mind raced as I tried to work out what was happening.","cn":"我拼命地转动脑筋，想搞清楚发生了什么事。"},"pos":"verb"},{"en":"to run too fast","cn":"运转过快；空转","g":"[intransitive]","sc":"of engine","ex":{"en":"The truck came to rest against a tree, its engine racing.","cn":"卡车撞上一棵树停了下来，引擎空转着。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（速度）比赛；竞赛","en":"A race is a competition to see who is the fastest, for example in running, swimming, or driving.","ex":{"en":"The women's race was won by the American, Patti Sue Plumer.","cn":"女子赛跑的冠军被美国人帕蒂·休·普卢默夺得。"}},{"pos":"VERB 动词","cn":"参赛;与…比赛","en":"If you race, you take part in a race.","ex":{"en":"In the 10 years I raced in Europe, 30 drivers were killed","cn":"在我10年的欧洲赛车生涯中，有30名车手丧生。"}},{"pos":"N-PLURAL 复数名词","cn":"赛马会","en":"The races are a series of horse races that are held in a particular place on a particular day. People go to watch and to bet on which horse will win.","ex":{"en":"The high point of this trip was a day at the races.","cn":"此行的高潮是去看赛马会的那一天。"}},{"pos":"N-COUNT 可数名词","cn":"竞争;角逐","en":"A race is a situation in which people or organizations compete with each other for power or control.","ex":{"en":"The race for the White House begins in earnest today","cn":"入主白宫的角逐今天正式开始。"}},{"pos":"N-VAR 可变名词","cn":"人种；种族","en":"A race is one of the major groups which human beings can be divided into according to their physical features, such as the colour of their skin.","ex":{"en":"The College welcomes students of all races, faiths, and nationalities","cn":"学院欢迎所有的学生，无论其种族、宗教信仰和国籍是什么。"}},{"pos":"VERB 动词","cn":"赶奔；疾走","en":"If you race somewhere, you go there as quickly as possible.","ex":{"en":"He raced across town to the State House building","cn":"他快速穿过市区赶往州议会大厦。"}},{"pos":"VERB 动词","cn":"（向某种状态或位置）急速发展，快速移动","en":"If something races towards a particular state or position, it moves very fast towards that state or position.","ex":{"en":"Do they realize we are racing towards complete economic collapse?","cn":"他们意识到我们的经济马上要彻底崩溃了吗？"}},{"pos":"VERB 动词","cn":"使（动物或车辆）参赛","en":"If you race a vehicle or animal, you prepare it for races and make it take part in races.","ex":{"en":"He still raced sports cars as often as he could.","cn":"他仍然尽可能经常地参加赛车比赛。"}},{"pos":"VERB 动词","cn":"（尤指在面临困难或危险时大脑）飞速运转","en":"If your mind races, or if thoughts race through your mind, you think very fast about something, especially when you are in a difficult or dangerous situation.","ex":{"en":"I made sure I sounded calm but my mind was racing","cn":"我确保自己听上去很镇定，但脑筋却飞快地转着。"}},{"pos":"VERB 动词","cn":"（心脏因兴奋或害怕）快速搏动，剧烈跳动","en":"If your heart races, it beats very quickly because you are excited or afraid.","ex":{"en":"Her heart raced uncontrollably.","cn":"她控制不住地心跳加速。"}},{"pos":"PHRASE 短语","cn":"与时间赛跑;争分夺秒","en":"You describe a situation as a race against time when you have to work very fast in order to do something before a particular time, or before another thing happens.","ex":{"en":"An air force spokesman said the rescue operation was a race against time.","cn":"一名空军发言人说这次营救行动是在和时间赛跑。"}}]},"media":{"uk":"media/uk/race__gb_1.mp3","us":"media/us/race__us_1.mp3"},"examples":[{"en":"He admired Canadians as a hardy and determined race.","cn":"他敬佩加拿大人，因为他们是吃苦耐劳、意志坚定的民族。"},{"en":"She took a deep breath to calm her racing pulse.","cn":"她深深地吸了口气，想使急速跳动的脉搏平静下来。"}]},"random":{"oxford":{"phon":"ˈrændəm","pos":"adjective","senses":[{"en":"done, chosen, etc. without somebody deciding in advance what is going to happen, or without any regular pattern","cn":"随机的，随意的（非事先决定或不规则）","g":"[usually before noun]","lab":"informal","ex":{"en":"the random killing of innocent people","cn":"对无辜者的随意杀戮"}},{"en":"not known or not identified","cn":"不认识的；辨认不出的","g":"[only before noun]","lab":"informal","ex":{"en":"Some random guy gave me a hundred bucks.","cn":"有个陌生男人给了我 100 美元。"}},{"en":"a thing or person that is random is strange and does not make sense, often in a way that interests you or makes you laugh","cn":"（人或物）不合常理的，出人意料的，不可思议的","lab":"informal","ex":{"en":"Mom, you are so random!","cn":"妈妈，你太不可思议了！"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"任意的；随机的；偶然的","en":"A random sample or method is one in which all the people or things involved have an equal chance of being chosen.","ex":{"en":"The survey used a random sample of two thousand people across England and Wales","cn":"该调查在英格兰和威尔士随机抽样了2,000人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"胡乱的；随便的","en":"If you describe events as random, you mean that they do not seem to follow a definite plan or pattern.","ex":{"en":"...random violence against innocent victims","cn":"加诸无辜受害者的无端暴行"}},{"pos":"PHRASE 短语","cn":"随机地；偶然地","en":"If you choose people or things at random, you do not use any particular method, so they all have an equal chance of being chosen.","ex":{"en":"We received several answers, and we picked one at random.","cn":"我们收到了一些答复，并从中随机挑选了一个。"}},{"pos":"PHRASE 短语","cn":"胡乱地；随便地；任意地","en":"If something happens at random, it happens without a definite plan or pattern.","ex":{"en":"Three black people were killed by shots fired at random from a minibus.","cn":"3名黑人被从一辆面包车里胡乱射出的子弹打死了。"}}]},"media":{"uk":"media/uk/random__gb_1.mp3","us":"media/us/random__us_1.mp3"},"examples":[{"en":"The humour is great because it's just so random and unhinged from reality.","cn":"幽默之妙在于它如此的出人意料又不受现实的束缚。"},{"en":"( informal ) He grabbed a pair of random jeans and an old red shirt.","cn":"他抓了一条随意拿到的牛仔裤和一件旧的红衬衫。"}]},"rationally":{"oxford":{"phon":"ˈræʃnəli","pos":"adverb","senses":[{"en":"in a way that is based on reason rather than emotion","cn":"合理的；理性的；明智的","ex":{"en":"to act/behave/think rationally","cn":"行动／举止／思考合情合理"}}]},"media":{"uk":"media/uk/rationally__gb_1.mp3","us":"media/us/rationally__us_1.mp3"},"examples":[{"en":"She argued her case calmly and rationally.","cn":"她冷静而又理智地为她的情况辩解。"},{"en":"to act/behave/think rationally","cn":"行动/举止/思考合情合理"}]},"rattle":{"media":{"uk":"media/uk/rattle__gb_1.mp3","us":"media/us/rattle__us_1.mp3","img":["media/ldoce/img/rattle.jpg"]},"oxford":{"phon":"ˈrætl","pos":"verb","senses":[{"en":"to make a series of short loud sounds when shaking or hitting against something hard; to make something do this","cn":"（使）发出咔嗒咔嗒的声音","g":"[intransitive, transitive]","ex":{"en":"Every time a bus went past, the windows rattled.","cn":"每次公共汽车经过这里，窗户都格格作响。"}},{"en":"to make a series of short loud sounds as it moves somewhere","cn":"（运行时）发出连续短促的高声","g":"[intransitive]","ex":{"en":"A convoy of trucks rattled by.","cn":"卡车队隆隆驶过。"}},{"en":"to make somebody nervous or frightened","cn":"使紧张；使恐惧","g":"[transitive]","ex":{"en":"He was clearly rattled by the question.","cn":"这个问题显然令他感到紧张。"}},{"en":"a series of short loud sounds made when hard objects hit against each other","cn":"一连串短促尖厉的撞击声；咔嗒声","g":"[usually singular]","ex":{"en":"the rattle of gunfire","cn":"轰隆轰隆的炮火声"},"pos":"noun"},{"en":"a baby’s toy that makes a series of short loud sounds when it is shaken","cn":"拨浪鼓","pos":"noun"},{"en":"a wooden object that is held in one hand and makes a series of short loud sounds when you turn it round, used, for example, by people watching a sports game","cn":"响板（在体育比赛等中观众用来助阵）","pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）发出震颤（或碰撞）声;（使）发出格格声","en":"When something rattles or when you rattle it, it makes short sharp knocking sounds because it is being shaken or it keeps hitting against something hard.","ex":{"en":"She slams the kitchen door so hard I hear dishes rattle","cn":"她把厨房门重重地关上，我甚至听到了碟子的震颤声。"}},{"pos":"N-COUNT 可数名词","cn":"拨浪鼓;摇铃","en":"A rattle is a baby's toy with loose bits inside which make a noise when the baby shakes it."},{"pos":"N-COUNT 可数名词","cn":"（在观看足球比赛或举行部落仪式中使用的）急响器，响板","en":"A rattle is a wooden instrument that people shake to make a loud knocking noise at football matches or tribal ceremonies."},{"pos":"N-COUNT 可数名词","cn":"（响尾蛇尾部的）角质环，响环","en":"A rattlesnake's rattle is the hard part at the end of its tail which makes a rattling sound when it is shaken."},{"pos":"VERB 动词","cn":"使紧张;使不安","en":"If something or someone rattles you, they make you nervous.","ex":{"en":"The news from Body Shop rattled the rest of the retail sector","cn":"从“美体小铺”传来的消息令整个零售行业不安。"}},{"pos":"VERB 动词","cn":"（巴士、火车或汽车）哐啷哐啷地行进，轰隆隆地开过","en":"You can say that a bus, train or car rattles somewhere when it moves noisily from one place to another.","ex":{"en":"The bus from Odense rattled into a dusty village called Pozo Almonte","cn":"从欧登塞来的巴士颠簸着驶入一个叫作波索阿尔蒙特的灰蒙蒙的村庄。"}},{"pos":"","cn":"","en":"相关词组：rattle around rattle off rattle on rattle through"}]},"examples":[{"en":"She spent the last few years alone, rattling around the old family home.","cn":"她在世的最后几年，一个人居住在空空荡荡的老宅子里。"},{"en":"She can rattle off the names of all the presidents of the US.","cn":"她可以不假思索地说出所有美国总统的名字。"}]},"rare":{"media":{"uk":"media/uk/rare__gb_1.mp3","us":"media/us/rare__us_1.mp3"},"oxford":{"phon":"reə(r)","pos":"adjective","senses":[{"en":"not done, seen, happening, etc. very often","cn":"稀少的；稀罕的","ex":{"en":"a rare disease/occurrence/event","cn":"罕见疾病／事情／事件"}},{"en":"existing only in small numbers and therefore valuable or interesting","cn":"稀罕的；珍贵的","ex":{"en":"a rare book","cn":"珍本"}},{"en":"cooked for only a short time so that the inside is still red","cn":"三分熟的","ex":{"en":"‘How would you like your steak?’ ‘Rare.’","cn":"“您的牛排想要什么口味？”“半生的。”"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稀有的；罕见的；珍奇的","en":"Something that is rare is not common and is therefore interesting or valuable.","ex":{"en":"...the black-necked crane, one of the rarest species in the world","cn":"黑颈鹤，世界最稀有的物种之一"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"少见的；不常发生的","en":"An event or situation that is rare does not occur very often.","ex":{"en":"...on those rare occasions when he did eat alone","cn":"在那些极其少见的、他的确单独吃饭的时候"}},{"pos":"ADJ 形容词","cn":"（品质）极好的，杰出的","en":"You use rare to emphasize an extremely good or remarkable quality.","ex":{"en":"Ferris has a rare ability to record her observations on paper","cn":"费里斯具备把自己的观察结果记录下来的超强能力。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（肉类）半熟的，嫩的","en":"Meat that is rare is cooked very lightly so that the inside is still red.","ex":{"en":"Thick tuna steaks are eaten rare, like beef","cn":"像牛肉一样，厚的金枪鱼排做到半熟即可食用。"}}]},"examples":[{"en":"On the rare occasions when they met he hardly even dared speak to her.","cn":"彼此难得相见，他还几乎不敢跟她说话。"},{"en":"It was a rare (= very great) honour to be made a fellow of the college.","cn":"成为这所学院的研究员是极大的荣誉。"}]},"rabbits":{"lemma":"rabbit"},"rack":{"media":{"img":["media/pic/rack_comp.jpg","media/thumb/rack.jpg"],"uk":"media/uk/rack__gb_1.mp3","us":"media/us/rack__us_1.mp3"},"oxford":{"phon":"ræk","pos":"noun","senses":[{"en":"a piece of equipment, usually made of metal or wooden bars, that is used for holding things or for hanging things on","cn":"支架；架子","ex":{"en":"a vegetable/wine/plate/toast rack","cn":"蔬菜架；酒瓶架；盘碟架；面包片架"}},{"en":"an instrument of torture, used in the past for punishing and hurting people. Their arms and legs were tied to the wooden frame and then pulled in opposite directions, stretching the body.","cn":"（旧时的）拉肢刑具"},{"en":"a particular piece of meat that includes the front ribs and is cooked in the oven","cn":"（羊、猪等带前肋的）颈脊肉"},{"en":"a part of a machine that consists of a bar with parts that a wheel or gear can fit into","cn":"（机器的）齿条，齿轨"},{"en":"to make somebody suffer great physical or mental pain","cn":"使痛苦不堪；使受折磨","lab":"British English","ex":{"en":"to be racked with/by guilt","cn":"深感内疚"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"挂物架；搁物架","en":"A rack is a frame or shelf, usually with bars or hooks, that is used for holding things or for hanging things on.","ex":{"en":"My rucksack was too big for the luggage rack","cn":"我的背包太大了，行李架上放不下。"}},{"pos":"VERB 动词","cn":"折磨;使痛苦","en":"If someone is racked by something such as illness or anxiety, it causes them great suffering or pain.","ex":{"en":"His already infirm body was racked by high fever","cn":"他已经很虚弱的身体受着高烧的折磨。"}},{"pos":"PHRASE 短语","cn":"绞尽脑汁；苦苦思索","en":"If you rack your brains, you try very hard to think of something.","ex":{"en":"She began to rack her brains to remember what had happened at the nursing home.","cn":"她开始绞尽脑汁地回忆在疗养院发生的事。"}},{"pos":"PHRASE 短语","cn":"（身体或心理）受到折磨","en":"If you say that someone is on the rack, you mean that they are suffering either physically or mentally.","ex":{"en":"Only a year ago, he was on the rack with a heroin addiction that began when he was 13.","cn":"就在一年前，他还被13岁时开始染上的海洛因毒瘾所折磨。"}},{"pos":"PHRASE 短语","cn":"荒废；衰败","en":"If you say that a place is going to rack and ruin, you are emphasizing that it is slowly becoming less attractive or less pleasant because no-one is bothering to look after it."},{"pos":"PHRASE 短语","cn":"（衣服、商品等）现成的，成品的","en":"Off-the-rack clothes or goods are made in large numbers, rather than being made specially for a particular person.","ex":{"en":"...the same off-the-rack dress she's been wearing since the night before","cn":"她从昨晚就一直穿着的同一件成品裙装"}},{"pos":"","cn":"","en":"相关词组：rack up"}]},"examples":[{"en":"In ten years of boxing he racked up a record 176 wins.","cn":"在十年的拳击生涯中，他累计获胜 176 次，创下纪录。"},{"en":"She racked her brains, trying to remember exactly what she had said.","cn":"她绞尽脑汁，想要回忆起她到底说过些什么话。"}]},"rather":{"media":{"uk":"media/uk/rather__gb_1.mp3","us":"media/us/rather__us_1.mp3"},"oxford":{"phon":"ˈrɑːðə(r)","pos":"adverb","senses":[{"en":"used to mean ‘fairly’ or ‘to some degree’, often when you are disappointed, surprised or expressing slight criticism","cn":"（常用于表示失望、惊讶或轻微的批评）相当，在某种程度上","lab":"North American English","ex":{"en":"rather odd/strange/unusual","cn":"相当怪异／奇怪／不寻常"}},{"en":"used with a verb to make a statement sound less strong","cn":"（与动词连用以减弱语气）有点儿，稍微","ex":{"en":"I've always rather liked Charlie.","cn":"我一直蛮喜欢查理的。"}},{"en":"used to correct something you have said, or to give more accurate information","cn":"（纠正所说的话或提供更确切的信息）更确切地讲，更准确地说","ex":{"en":"She worked as a secretary, or rather, a personal assistant.","cn":"她当了秘书；确切地讲，是私人助理。"}},{"en":"used to introduce an idea that is different or opposite to the idea that you have stated previously","cn":"（提出不同或相反的观点）相反，反而，而是","ex":{"en":"The walls were not white, but rather a sort of dirty grey.","cn":"墙面不是白的，而是灰不溜秋的。"}},{"en":"used to agree with somebody’s suggestion","cn":"（表示同意某人的提议）","ex":{"en":"‘How about a trip to the beach?’ ‘Rather!’","cn":"“去海边旅游怎么样？”“太好了！”"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"PREP-PHRASE 短语介词","cn":"而非；胜于；而不是","en":"You use rather than when you are contrasting two things or situations. Rather than introduces the thing or situation that is not true or that you do not want.","ex":{"en":"The problem was psychological rather than physiological","cn":"问题是心理方面的而不是生理方面的。"}},{"pos":"ADV 副词","cn":"而是；更确切地说；还不如说；相反","en":"You use rather when you are correcting something that you have just said, especially when you are describing a particular situation after saying what it is not.","ex":{"en":"Twenty million years ago, Idaho was not the arid place it is now. Rather, it was warm and damp, populated by dense primordial forest","cn":"2,000万年前，爱达荷州并不像现在这样干旱。相反，那时的爱达荷州温暖潮湿，有大片的原始森林。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"宁愿/不愿；宁可/宁可不","en":"If you say that you would rather do something or you'd rather do it, you mean that you would prefer to do it. If you say that you would rather not do something, you mean that you do not want to do it.","ex":{"en":"If it's all the same to you, I'd rather work at home","cn":"如果对你来说没什么差别，我宁愿在家中工作。"}},{"pos":"ADV 副词","cn":"有些;颇为;相当","en":"You use rather to indicate that something is true to a fairly great extent, especially when you are talking about something unpleasant or undesirable.","ex":{"en":"I grew up in rather unusual circumstances","cn":"我在非同寻常的环境下长大。"}},{"pos":"ADV 副词","cn":"（放在动词前）更…，宁愿…","en":"You use rather before verbs that introduce your thoughts and feelings, in order to express your opinion politely, especially when a different opinion has been expressed.","ex":{"en":"I rather think he was telling the truth","cn":"我倒觉得他讲的是真话。"}},{"pos":"CONVENTION 惯用语","cn":"（表示同意或接受）当然，的确","en":"People sometimes say rather to express agreement or acceptance.","ex":{"en":"'Well, he did have a sort of family connection with it, didn't he.' — 'Oh yes. Rather.'","cn":"“那么，他的确和它有些家族渊源，是不是？”——“噢，是的，的确如此。”"}}]},"examples":[{"en":"In the end he had to walk — or rather run — to the office.","cn":"最后他不得不走着，应该说是跑着，去办公室。"},{"en":"‘Do you want to come with us?’ ‘No, I'd rather not.’ “","cn":"你想跟我们一起来吗？” “不，我不想去。”"}]},"rails":{"lemma":"rail","media":{"img":["media/pic/trains_comp.jpg","media/thumb/freighttrain.jpg"],"uk":"media/uk/rail__gb_1.mp3","us":"media/us/rail__us_1.mp3"}},"rarely":{"media":{"uk":"media/uk/rarely__gb_1.mp3","us":"media/us/rarely__us_1.mp3"},"oxford":{"phon":"ˈreəli","pos":"adverb","senses":[{"en":"not very often","cn":"罕有；很少；不常","lab":"formal","ex":{"en":"She is rarely seen in public nowadays.","cn":"如今在公共场所很少能见到她。"}}]},"collins":{"senses":[{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"难得地；少见地","en":"If something rarely happens, it does not happen very often.","ex":{"en":"They battled against other Indian tribes, but rarely fought with the whites","cn":"他们同其他印第安部落作战，但很少与白人并肩对敌。"}}]},"examples":[{"en":"We rarely agree on what to do.","cn":"我们很少在要做的事情上看法一致。"},{"en":"( formal ) Rarely has a debate attracted so much media attention.","cn":"很少有辩论吸引这么多媒体关注。"}]},"razor":{"oxford":{"phon":"ˈreɪzə(r)","pos":"noun","senses":[{"en":"an instrument that is used for removing hair by shaving","cn":"剃须刀；刮脸刀","ex":{"en":"a disposable razor","cn":"一次性剃须刀"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"剃刀；刮胡刀","en":"A razor is a tool that people use for shaving."}]},"media":{"uk":"media/uk/razor__gb_1.mp3","us":"media/us/razor__us_1.mp3","img":["media/ldoce/img/razor.jpg"]},"examples":[{"en":"a cut-throat/safety/disposable razor","cn":"开式/保险/一次性剃刀"},{"en":"an electric razor","cn":"电动剃须刀"}]},"ranking":{"media":{"uk":"media/uk/ranking__gb_1.mp3","us":"media/us/ranking__us_1.mp3"},"oxford":{"phon":"ˈræŋkɪŋ","pos":"noun","senses":[{"en":"the position of somebody/something on a scale that shows how good or important they are in relation to other similar people or things, especially in sport","cn":"地位，排名，排位（尤指在体育运动中）","ex":{"en":"He has improved his ranking this season from 67th to 30th.","cn":"本赛季他将自己的排名从第 67 位提高到了第 30 位。"}},{"en":"an official list showing the best players of a particular sport in order of how successful they are","cn":"（某项体育运动的）最佳运动员排名表","g":"[plural]","ex":{"en":"He is currently 16th in the world rankings.","cn":"目前他的世界排名是第16位。"}},{"en":"having a high or the highest rank in an organization, etc.","cn":"地位高的；高级的；最高级的","ex":{"en":"a ranking diplomat","cn":"高级外交官"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"（最优秀选手的）排名（表），名次表","en":"In many sports, the list of the best players made by an official organization is called the rankings.","ex":{"en":"...the 25 leading teams in the world rankings","cn":"世界排名前25的队"}},{"pos":"N-COUNT 可数名词","cn":"等级；名次","en":"Someone's ranking is their position in an official list of the best players of a sport.","ex":{"en":"Agassi was playing well above his world ranking of 12.","cn":"阿加西的比赛表现大大超出了他在世界上第12位的排名。"}},{"pos":"ADJ 形容词","cn":"（常指政治团体中的成员）首位的，最高级别的","en":"The ranking member of a group, usually a political group, is the most senior person in it.","ex":{"en":"...the ranking Republican on the senate intelligence committee.","cn":"参议院情报委员会中最资深的共和党人"}}]},"examples":[{"en":"He has improved his ranking this season from 67th to 30th.","cn":"本赛季他将自己的排名从第 67 位提高到了第 30 位。"},{"en":"She has retained her No.1 world ranking.","cn":"她保住了自己世界第一的排名。"}],"base":"rank"},"rag":{"media":{"uk":"media/uk/rag__gb_1.mp3","us":"media/us/rag__us_1.mp3"},"oxford":{"phon":"ræɡ","pos":"noun","senses":[{"en":"a piece of old, often torn, cloth used especially for cleaning things","cn":"抹布；破布","g":"[countable, uncountable]","ex":{"en":"I wiped the window with a damp rag.","cn":"我用湿抹布擦了擦窗户。"}},{"en":"a newspaper that you believe to be of low quality","cn":"质量低劣的报纸；小报","g":"[countable]","lab":"informal, usually disapproving，，","ex":{"en":"the local rag","cn":"地方小报"}},{"en":"a piece of ragtime music","cn":"雷格泰姆乐曲","g":"[countable]"},{"en":"an event or a series of events organized by students each year to raise money for charity","cn":"（学生每年组织的）慈善募捐活动","g":"[uncountable, countable]","lab":"British English","ex":{"en":"rag week","cn":"学生募捐周"}},{"en":"to laugh at and/or play tricks on somebody","cn":"嘲笑；捉弄","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"抹布；破布；碎布","en":"A rag is a piece of old cloth which you can use to clean or wipe things.","ex":{"en":"He was wiping his hands on an oily rag.","cn":"他正在用一块满是油污的破布擦手。"}},{"pos":"N-PLURAL 复数名词","cn":"破旧衣服；破烂衣裳","en":"Rags are old torn clothes.","ex":{"en":"There were men, women and small children, some dressed in rags.","cn":"有男人、女人和小孩，其中一些人衣衫褴褛。"}},{"pos":"N-COUNT 可数名词","cn":"（格调低下的）报纸，小报","en":"People refer to a newspaper as a rag when they have a poor opinion of it.","ex":{"en":"'This man Tom works for a local rag,' he said.","cn":"“这个叫汤姆的人在一家地方小报社工作，”他说。"}},{"pos":"VERB 动词","cn":"嘲弄；拿…开玩笑；对…恶作剧","en":"To rag someone means to make fun of them in an unkind way.","ex":{"en":"She was about thirty, ten years older than the youngsters ragging her.","cn":"她大概有30岁，比那些嘲弄她的年轻人大10岁。"}},{"pos":"PHRASE 短语","cn":"突然生气；勃然大怒","en":"If you lose your rag, you suddenly become so angry that you are not in control of yourself.","ex":{"en":"I've only once seen him lose his rag.","cn":"我只见他发过一次脾气。"}},{"pos":"PHRASE 短语","cn":"从赤贫到巨富;白手起家","en":"You use rags to riches to describe the way in which someone quickly becomes very rich after they have been quite poor.","ex":{"en":"His was a rags-to-riches story and people admire that.","cn":"他白手起家，人们对他都很钦佩。"}},{"pos":"PHRASE 短语","cn":"激怒人的东西","en":"If you describe something as a red rag to a bull, you mean that it is certain to make a particular person or group very angry.","ex":{"en":"This sort of information is like a red rag to a bull for the tobacco companies.","cn":"烟草公司知道了这种消息一定会大怒。"}}]},"examples":[{"en":"Hers was a classic tale of rags to riches.","cn":"她的经历是从赤贫到富有的一个典型例子。"},{"en":"The children were dressed in rags.","cn":"孩子们穿着破衣烂衫。"}]},"radiocarbon":{"media":{"uk":"media/uk/radiocarbon__gb_1.mp3","us":"media/us/radiocarbon__us_1.mp3"},"oxford":{"phon":"ˌreɪdiəʊˈkɑːbən","pos":"noun","senses":[{"en":"a radioactive form of carbon that is present in the materials of which living things are formed, used in carbon dating","cn":"放射性碳（碳的放射性同位素，用以测定物体的年代）","ex":{"en":"radiocarbon analysis","cn":"放射性碳分析"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"放射性碳","en":"Radiocarbon is a type of carbon which is radioactive, and which therefore breaks up slowly at a regular rate. Its presence in an object can be measured in order to find out how old the object is.","ex":{"en":"The most frequently used method is radiocarbon dating.","cn":"最常用的方法是放射性碳定年法。"}}]},"examples":[{"en":"radiocarbon analysis","cn":"放射性碳分析"}]},"ratio":{"media":{"uk":"media/uk/ratio__gb_1.mp3","us":"media/us/ratio__us_1.mp3"},"oxford":{"phon":"ˈreɪʃiəʊ","pos":"noun","senses":[{"en":"the relationship between two groups of people or things that is represented by two numbers showing how much larger one group is than the other","cn":"比率；比例","ex":{"en":"The school has a very high teacher-student ratio.","cn":"这所学校的师生比例很高。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"比;比率;比例","en":"A ratio is a relationship between two things when it is expressed in numbers or amounts. For example, if there are ten boys and thirty girls in a room, the ratio of boys to girls is 1:3, or one to three.","ex":{"en":"In 1978 there were 884 students at a lecturer/student ratio of 1:15","cn":"1978年有884名学生，师生比为1比15。"}}]},"examples":[{"en":"The ratio of applications to available places currently stands at 100:1.","cn":"目前，申请人数和录取名额的比例为 100:1。"},{"en":"What is the ratio of men to women in the department?","cn":"这个部门的男女比例是多少？"}]},"rarefied":{"media":{"uk":"media/uk/rarefied__gb_1.mp3","us":"media/us/rarefied__us_1.mp3"},"oxford":{"phon":"ˈreərɪfaɪd","pos":"adjective","senses":[{"en":"understood or experienced by only a very small group of people who share a particular area of knowledge or activity","cn":"高深精妙的；曲高和寡的","lab":"often disapproving","ex":{"en":"the rarefied atmosphere of academic life","cn":"阳春白雪的学术生活氛围"}},{"en":"containing less oxygen than usual","cn":"稀薄的；含氧量低的","ex":{"en":"Climbers may experience difficulty breathing in the rarefied air at high altitudes.","cn":"登山者在高海拔地区稀薄的空气中可能会感到呼吸困难。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过于高雅的;过于高贵的;脱离现实生活的","en":"If you talk about the rarefied atmosphere of a place or institution, you are expressing your disapproval of it, because it has a special social or academic status that makes it very different from ordinary life.","ex":{"en":"...the fear and loneliness that working class students can feel when they are plunged into the rarefied atmosphere of university","cn":"工人阶级出身的学生面对大学静雅高深的氛围时产生的恐惧和孤独"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（空气）稀薄的，含氧量少的","en":"Rarefied air is air that does not contain much oxygen, for example in mountain areas.","ex":{"en":"Both animals and people were gasping for breath in the rarefied air.","cn":"动物和人在稀薄的空气中都大口喘着气。"}}]},"examples":[{"en":"the rarefied atmosphere of academic life","cn":"阳春白雪的学术生活氛围"},{"en":"the rarefied atmosphere of academia","cn":"曲高和寡的学术界氛围"}]},"radiant":{"media":{"uk":"media/uk/radiant__gb_1.mp3","us":"media/us/radiant__us_1.mp3"},"oxford":{"phon":"ˈreɪdiənt","pos":"adjective","senses":[{"en":"showing great happiness, love or health","cn":"喜气洋洋的；容光焕发的；面色红润的","ex":{"en":"a radiant smile","cn":"喜气洋洋的微笑"}},{"en":"giving a warm bright light","cn":"灿烂的；光芒四射的","ex":{"en":"The sun was radiant in a clear blue sky.","cn":"湛蓝的天空阳光灿烂。"}},{"en":"sent out in rays from a central point","cn":"辐射的；放射的","g":"[only before noun]","lab":"specialist","ex":{"en":"the radiant heat/energy of the sun","cn":"太阳的辐射热／辐射能"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"容光焕发的;喜气洋洋的","en":"Someone who is radiant is so happy that their happiness shows in their face.","ex":{"en":"Kathy smiled at her daughter's radiant face","cn":"凯茜对着女儿容光焕发的面孔微笑着。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"光辉灿烂的；光芒四射的","en":"Something that is radiant glows brightly.","ex":{"en":"The evening sun warms the old red brick wall to a radiant glow.","cn":"夕阳为古老的红砖墙罩上了一层暖暖的炫目光辉。"}},{"pos":"ADJ 形容词","cn":"（热量、能量等）辐射的","en":"Radiant heat or energy is sent out in the form of rays.","ex":{"en":"The earth would be a frozen ball if it were not for the radiant heat of the sun.","cn":"如果没有太阳辐射的热量，地球将是一个冰封的世界。"}}]},"examples":[{"en":"She was radiant with health.","cn":"她身体健康，容光焕发。"},{"en":"The bride looked radiant.","cn":"新娘看上去满面春风。"}]},"racing":{"oxford":{"phon":"ˈreɪsɪŋ","pos":"noun","senses":[{"en":"the sport of racing horses","cn":"赛马","lab":"especially North American English, Australian English, New Zealand English，，，，","ex":{"en":"He used to watch the racing on TV in the afternoons.","cn":"他过去常常下午在电视上看赛马。"}},{"en":"any sport that involves competing in races","cn":"速度比赛","ex":{"en":"yacht/motorcycle racing","cn":"帆船／摩托车比赛"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"动物赛跑比赛;(尤指)赛马;赛车","en":"Racing refers to races between animals, especially horses, or between vehicles.","ex":{"en":"Mr Honda was himself a keen racing driver in his younger days","cn":"本田先生自己年轻时就是位热衷赛车的车手。"}}]},"media":{"uk":"media/uk/racing__gb_1.mp3","us":"media/us/racing__us_1.mp3"},"examples":[{"en":"motor/yacht/greyhound, etc. racing","cn":"摩托车赛、快艇赛、赛狗等"},{"en":"a racing stable","cn":"赛马马厩"}],"base":"race"},"raising":{"media":{"uk":"media/uk/raising__gb_1.mp3","us":"media/us/raising__us_1.mp3"},"oxford":{"phon":"ˈreɪzɪŋ","pos":"noun","senses":[{"en":"the act of raising something","cn":"增加；提高","ex":{"en":"consciousness raising","cn":"觉悟的提高"}}]},"examples":[{"en":"a raising of standards in schools","cn":"学校水平的提高"},{"en":"consciousness raising","cn":"觉悟的提高"}],"base":"raise"},"rally":{"media":{"uk":"media/uk/rally__gb_1.mp3","us":"media/us/rally__us_1.mp3"},"oxford":{"phon":"ˈræli","pos":"noun","senses":[{"en":"a large public meeting, especially one held to support a particular idea or political party","cn":"公众集会，群众大会（尤指支持某信念或政党）","g":"[countable]","ex":{"en":"to attend/hold a rally","cn":"参加／召集大会"}},{"en":"a race for cars, motorcycles, etc. over public roads","cn":"拉力赛车","g":"[countable]","ex":{"en":"the Monte Carlo rally","cn":"蒙特卡洛汽车拉力赛"}},{"en":"a series of hits of the ball before a point is scored","cn":"（争夺一分的）多拍，多拍回合","g":"[countable]","ex":{"en":"That was a great rally!","cn":"那是一次伟大的集会！"}},{"en":"an act of returning to a strong position after a period of difficulty or weakness","cn":"止跌回升","g":"[singular]","ex":{"en":"After a furious late rally, they finally scored.","cn":"他们后来状态恢复迅速，终于得分了。"}},{"en":"to come together or bring people together in order to help or support somebody/something","cn":"召集；集合","g":"[intransitive, transitive]","ex":{"en":"The cabinet rallied behind the Prime Minister.","cn":"内阁团结一致支持首相。"},"pos":"verb"},{"en":"to become healthier, stronger, etc. after a period of illness, weakness, etc.","cn":"复原；恢复健康；振作精神","g":"[intransitive]","ex":{"en":"He never really rallied after the operation.","cn":"手术后，他根本没有真正康复。"},"pos":"verb"},{"en":"to increase in value after falling in value","cn":"价格回升；跌后回升","g":"[intransitive]","lab":"finance","ex":{"en":"The company's shares had rallied slightly by the close of trading.","cn":"这家公司的股票价格在收盘前略有回升。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"群众大会；集会","en":"A rally is a large public meeting that is held in order to show support for something such as a political party.","ex":{"en":"About three thousand people held a rally to mark international human rights day","cn":"大约3,000人举行了一场大会来庆祝国际人权日。"}},{"pos":"V-ERG 及物/不及物动词","cn":"一致支持；团结起来","en":"When people rally to something or when something rallies them, they unite to support it.","ex":{"en":"His supporters have rallied to his defence","cn":"他的拥护者团结起来为他辩护。"}},{"pos":"VERB 动词","cn":"振作；恢复","en":"When someone or something rallies, they begin to recover or improve after having been weak.","ex":{"en":"He rallied enough to thank his doctors","cn":"他身体好得差不多了，于是去感谢他的医生。"}},{"pos":"N-COUNT 可数名词","cn":"（汽车、摩托车等的）公路大赛","en":"A rally is a competition in which vehicles are driven over public roads.","ex":{"en":"Carlos Sainz of Spain has won the New Zealand Motor Rally.","cn":"西班牙人卡洛斯·赛恩斯在新西兰摩托车公路大赛中夺冠。"}},{"pos":"N-COUNT 可数名词","cn":"（网球、羽毛球、壁球等的）连续对打","en":"A rally in tennis, badminton, or squash is a continuous series of shots that the players exchange without stopping.","ex":{"en":"...a long rally.","cn":"长时间的连续对打"}},{"pos":"","cn":"","en":"相关词组：rally around"}]},"examples":[{"en":"The champion rallied to win the second set 6–3.","cn":"冠军选手振作精神，以 6:3 赢下第二局。"},{"en":"The company's shares had rallied slightly by the close of trading.","cn":"这家公司的股票价格在收盘前略有回升。"}]},"range":{"media":{"uk":"media/uk/range__gb_1.mp3","us":"media/us/range__us_1.mp3"},"oxford":{"phon":"reɪndʒ","pos":"noun","senses":[{"en":"a variety of things of a particular type","cn":"一系列","g":"[countable, usually singular]","sc":"variety","ex":{"en":"The hotel offers a wide range of facilities.","cn":"这家酒店提供各种各样的设施。"}},{"en":"a set of products of a particular type","cn":"类；种","g":"[countable]","sc":"of products","ex":{"en":"our new range of hair products","cn":"我们新的洗发护发产品系列"}},{"en":"the limits between which something varies","cn":"（变动或浮动的）范围，界限，区间","g":"[countable, usually singular]","sc":"limits/extent","ex":{"en":"Most of the students are in the 17–20 age range.","cn":"大多数学生都是在 17 至 20 岁的年龄范围内。"}},{"en":"the extent of somebody's knowledge or abilities","cn":"（知识或能力的）范围","g":"[countable, usually singular]","sc":"limits/extent","ex":{"en":"I think she has quite a limited range as an actor.","cn":"我认为她的表演才能相当有限。"}},{"en":"the area covered by or included in something","cn":"（涵盖的）范围，方面","g":"[countable, usually singular]","sc":"limits/extent","ex":{"en":"Her sculptures explore the range of human experience.","cn":"她的雕塑探索了人类体验的方方面面。"}},{"en":"the distance over which something can be seen or heard","cn":"视觉（或听觉）范围","g":"[countable, uncountable]","sc":"distance","ex":{"en":"The child was now out of her range of vision (= not near enough for her to see).","cn":"这孩子已经走出了她的视线。"}},{"en":"the distance over which a gun or other weapon can hit things","cn":"射程；射击距离","g":"[countable, uncountable]","sc":"distance","ex":{"en":"These missiles have a range of 300 miles.","cn":"这些导弹的射程为 300 英里。"}},{"en":"the distance that a vehicle will travel before it needs more fuel","cn":"（车辆）加一次油可行驶的路程","g":"[countable]","sc":"distance"},{"en":"a line or group of mountains or hills","cn":"山脉","g":"[countable]","sc":"of mountains","ex":{"en":"the great mountain range of the Alps","cn":"雄伟的阿尔卑斯山脉"}},{"en":"an area of land where people can practise shooting or where bombs, etc. can be tested","cn":"靶场；射击场；炸弹试验场","g":"[countable]","sc":"for shooting","ex":{"en":"a shooting range","cn":"射击场"}},{"en":"a large piece of equipment that can burn various fuels and is kept hot all the time, used for cooking, especially in the past","cn":"（尤指旧时的）炉灶","g":"[countable]","sc":"oven"},{"en":"a large piece of equipment for cooking food, containing an oven and gas or electric rings on top","cn":"（带烤箱、燃气炉或电炉的）厨灶，炉具","g":"[countable]","lab":"North American English","sc":"oven","ex":{"en":"Cook the meat on a low heat on top of the range.","cn":"把肉放在炉灶上用文火炖着。"}},{"en":"a large open area for keeping cows, etc.","cn":"牧场；乳牛场","g":"[singular]","lab":"North American English","sc":"for cows"},{"en":"to vary between two particular amounts, sizes, etc., including others between them","cn":"（在一定的范围内）变化，变动","g":"[intransitive]","sc":"vary","ex":{"en":"Accommodation ranges from tourist class to luxury hotels.","cn":"住宿档次从经济旅馆至豪华酒店不等。"},"pos":"verb"},{"en":"to include a variety of different things in addition to those mentioned","cn":"包括（从…到…）之间的各类事物","g":"[intransitive]","sc":"vary","ex":{"en":"She has had a number of different jobs, ranging from chef to swimming instructor.","cn":"她做过许多不同的工作，从厨师到游泳教练。"},"pos":"verb"},{"en":"to arrange people or things in a particular position or order","cn":"（按一定位置或顺序）排列，排序","g":"[transitive, often passive]","lab":"formal","sc":"arrange","ex":{"en":"The delegates ranged themselves around the table.","cn":"代表依次在桌子周围就座。"},"pos":"verb"},{"en":"to move around an area","cn":"徘徊；漫步；四处移动","g":"[intransitive, transitive]","sc":"move around","ex":{"en":"He ranges far and wide in search of inspiration for his paintings.","cn":"他四处漫步，寻找绘画的灵感。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（同类事物的）一系列，一连串","en":"A range of things is a number of different things of the same general kind.","ex":{"en":"A wide range of colours and patterns are available","cn":"各种颜色和样式都有。"}},{"pos":"N-COUNT 可数名词","cn":"幅度;等级;范围","en":"A range is the complete group that is included between two points on a scale of measurement or quality.","ex":{"en":"The average age range is between 35 and 55.","cn":"平均年龄在35岁到55岁之间。"}},{"pos":"N-COUNT 可数名词","cn":"最大范围;射程","en":"The range of something is the maximum area in which it can reach things or detect things.","ex":{"en":"The 120mm mortar has a range of 18,000 yards","cn":"口径为120毫米的迫击炮的射程是1.8万码。"}},{"pos":"VERB 动词","cn":"（在一定幅度内）变化，变动","en":"If things range between two points or range from one point to another, they vary within these points on a scale of measurement or quality.","ex":{"en":"They range in price from $3 to $15.","cn":"它们的价格从3美元到15美元不等。"}},{"pos":"VERB 动词","cn":"（文章或讲话）涉及，包括","en":"If a piece of writing or speech ranges over a group of topics, it includes all those topics.","ex":{"en":"The conversation ranged over the desirability of such restaurants, the shortcomings of men, and why it had only taken 15 minutes to cross a continent.","cn":"谈话涉及了这类餐馆的吸引人之处、男人的弱点，还有为什么只用15分钟就跨越了一个大洲。"}},{"pos":"VERB 动词","cn":"使（人或物）排成行或列","en":"If people or things are ranged somewhere, they are arranged in a row or in lines.","ex":{"en":"Some 300 trees have been ranged along the perimeter hedge","cn":"沿着绿篱栽种着大约300棵树。"}},{"pos":"VERB 动词","cn":"（人或动物）漫游，自由活动","en":"If animals or people range somewhere, they move around in a place without having a particular destination in mind.","ex":{"en":"Feeding is not a problem because the birds range over such a large area","cn":"这种鸟活动的范围很大，因此觅食不成问题。"}},{"pos":"N-COUNT 可数名词","cn":"山脉","en":"A range of mountains or hills is a line of them.","ex":{"en":"...the massive mountain ranges to the north.","cn":"向北延伸的巨大山脉"}},{"pos":"N-COUNT 可数名词","cn":"（尤指美国的）牧牛场，牧区","en":"A range is a large area of open land, especially land in the United States where cattle are kept."},{"pos":"N-COUNT 可数名词","cn":"射击场；靶场","en":"A rifle range or a shooting range is a place where people can practise shooting at targets.","ex":{"en":"It reminds me of my days on the rifle range preparing for duty in Vietnam.","cn":"它使我想起了在靶场练习射击准备去越南服役的日子。"}},{"pos":"N-COUNT 可数名词","cn":"（旧式）炊具","en":"A range or kitchen range is an old-fashioned metal cooker."},{"pos":"N-COUNT 可数名词","cn":"炉灶","en":"A range or kitchen range is a large metal device for cooking food using gas or electricity. A range consists of a grill, an oven, and some gas or electric rings."},{"pos":"PHRASE 短语","cn":"在可及的范围内/在可及的范围外","en":"If something is in range or within range, it is near enough to be reached or detected. If it is out of range, it is too far away to be reached or detected.","ex":{"en":"Cars are driven through the mess, splashing everyone in range.","cn":"车从脏水里驶过，溅了周围所有人一身水。"}},{"pos":"PHRASE 短语","cn":"接近地/靠近地/以…的距离","en":"If you see or hit something at close range or from close range, you are very close to it when you see it or hit it. If you do something at a range of half a mile, for example, you are half a mile away from it when you do it.","ex":{"en":"He was shot in the head at close range","cn":"他在近距离内被人用枪击中头部。"}}]},"examples":[{"en":"Most of the students are in the 17-20 age range.","cn":"大多数学生都是在 17 至 20 岁的年龄范围内。"},{"en":"Estimates of the damage range between $1 million and $5 million.","cn":"估计损失在 100 万到 500 万元之间。"}]},"radiators":{"lemma":"radiator","media":{"uk":"media/uk/radiator__gb_1.mp3","us":"media/us/radiator__us_1.mp3"}},"railroad":{"media":{"uk":"media/uk/railroad__gb_1.mp3","us":"media/us/railroad__us_1.mp3","img":["media/ldoce/img/track.jpg"]},"oxford":{"phon":"ˈreɪlrəʊd","pos":"noun","senses":[{"en":"a track with rails on which trains run","cn":"铁路；铁道","lab":"British English also","ex":{"en":"railroad tracks","cn":"铁路轨道"}},{"en":"a system of tracks, together with the trains that run on them, and the organization and people needed to operate them","cn":"铁路系统；铁路公司；铁道部门","ex":{"en":"This town got a lot bigger when the railroad came in the 1860s.","cn":"自从 19 世纪 60 年代通了火车之后，这座城镇变大了许多。"}},{"en":"to force somebody to do something before they have had enough time to decide whether or not they want to do it","cn":"迫使…仓促行事；强迫…做","ex":{"en":"I will not be railroaded into signing something I don't agree with.","cn":"我不会被迫签署我不同意的东西。"},"pos":"verb"},{"en":"to make a group of people accept a decision, law, etc. quickly by putting pressure on them","cn":"强使（决定、法律等）草率通过","ex":{"en":"The bill was railroaded through the House.","cn":"议院不得已草率通过了这项提案。"},"pos":"verb"},{"en":"to decide that somebody is guilty of a crime, without giving them a fair trial","cn":"轻率判处","lab":"North American English","ex":{"en":"He knows he's being railroaded.","cn":"他知道他正在被铁路束缚。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"铁路；铁道","en":"A railroad is a route between two places along which trains travel on steel rails.","ex":{"en":"...railroad tracks that led to nowhere","cn":"向远方延伸的铁轨"}},{"pos":"N-COUNT 可数名词","cn":"铁路公司；铁路部门","en":"A railroad is a company or organization that operates railway routes.","ex":{"en":"...The Chicago and Northwestern Railroad.","cn":"芝加哥和西北铁路公司"}},{"pos":"VERB 动词","cn":"强迫，迫使（某人仓促行事）","en":"If you railroad someone into doing something, you make them do it although they do not really want to, by hurrying them and putting pressure on them.","ex":{"en":"He more or less railroaded the rest of Europe into recognising the new 'independent' states","cn":"他几乎是迫使着其他欧洲国家承认了那些新兴的“独立”国家。"}}]},"examples":[{"en":"This town got a lot bigger when the railroad came in the 1860s.","cn":"自从 19 世纪 60 年代通了火车之后，这座城镇变大了许多。"},{"en":"The bill was railroaded through the House.","cn":"议院不得已草率通过了这项提案。"}]},"railroader":{"media":{"uk":"media/uk/railroader__gb_1.mp3","us":"media/us/railroader__us_1.mp3"},"oxford":{"phon":"ˈreɪlrəʊdə(r)","pos":"noun","senses":[{"en":"a person who works for a railway company","cn":"铁路工人；铁路员工"}]}},"radio":{"media":{"uk":"media/uk/radio__gb_1.mp3","us":"media/us/radio__us_1.mp3"},"oxford":{"phon":"ˈreɪdiəʊ","pos":"noun","senses":[{"en":"the activity of broadcasting programmes for people to listen to; the programmes that are broadcast","cn":"无线电广播；无线电广播节目","g":"[uncountable, singular]","ex":{"en":"The play was written specially for radio.","cn":"这出戏是专为无线电广播而写的。"}},{"en":"a piece of equipment used for listening to programmes that are broadcast to the public","cn":"收音机","g":"[countable]","ex":{"en":"to turn the radio on/off","cn":"打开／关上收音机"}},{"en":"the process of sending and receiving messages through the air using electromagnetic waves","cn":"无线电传送；无线电通信","g":"[uncountable]","ex":{"en":"He was unable to contact Blake by radio.","cn":"他未能通过无线电和布莱克取得联系。"}},{"en":"a piece of equipment, for example on ships or planes, for sending and receiving radio signals","cn":"无线电收发报机","g":"[countable]","ex":{"en":"They heard the gale warning over the ship’s radio.","cn":"他们从船上的无线电设备听到大风警报。"}},{"en":"to send a message to somebody by radio","cn":"（用无线电）发送，传送","ex":{"en":"The police officer radioed for help.","cn":"警察用无线电呼救。"},"pos":"verb"},{"en":"connected with radio waves or broadcasting","cn":"无线电波的；无线电广播的","ex":{"en":"radio-controlled","cn":"无线电遥控的"},"pos":"combining form"},{"en":"connected with radioactivity","cn":"放射的；辐射的","ex":{"en":"radiotherapy","cn":"放射疗法"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无线电广播","en":"Radio is the broadcasting of programmes for the public to listen to, by sending out signals from a transmitter.","ex":{"en":"The last 12 months have been difficult ones for local radio","cn":"对于当地广播台来说，过去的12个月很艰难。"}},{"pos":"N-SING 单数名词","cn":"无线电广播节目","en":"You can refer to the programmes broadcast by radio stations as the radio .","ex":{"en":"A lot of people tend to listen to the radio in the mornings","cn":"许多人喜欢在早上听广播。"}},{"pos":"N-COUNT 可数名词","cn":"收音机","en":"A radio is the piece of equipment that you use in order to listen to radio programmes.","ex":{"en":"He sat down in the armchair and turned on the radio.","cn":"他在扶手椅中坐下，打开了收音机。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"无线电；无线电通讯","en":"Radio is a system of sending sound over a distance by transmitting electrical signals.","ex":{"en":"They are in twice daily radio contact with the rebel leader.","cn":"他们每天用无线电和叛军首领联系两次。"}},{"pos":"N-COUNT 可数名词","cn":"无线电收发设备","en":"A radio is a piece of equipment that is used for sending and receiving messages.","ex":{"en":"...the young constable who managed to raise the alarm on his radio","cn":"通过无线电设备发出警报的年轻警官"}},{"pos":"VERB 动词","cn":"用无线电向…发送信息","en":"If you radio someone, you send a message to them by radio.","ex":{"en":"The officer radioed for advice","cn":"军官发来无线电报请求指示。"}}]},"examples":[{"en":"Did you hear the interview with him on the radio?","cn":"你有没有在广播里听到采访他的情况？"},{"en":"He was unable to contact Blake by radio.","cn":"他未能通过无线电和布莱克取得联系。"}]},"rand":{"oxford":{"phon":"rænd","pos":"noun","senses":[{"en":"the unit of money in the Republic of South Africa","cn":"兰特（南非共和国货币单位）","g":"[countable]"},{"en":"(in South Africa) a large area around Johannesburg where gold is mined and where there are many cities and towns","cn":"兰德（南非约翰内斯堡周围的金矿区）","g":"[singular]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兰特（南非货币单位）","en":"The rand is the unit of currency used in South Africa.","ex":{"en":"...12 million rand.","cn":"1,200万兰特"}}]},"media":{"uk":"media/uk/rand__gb_1.mp3","us":"media/us/rand__us_1.mp3"}},"radical":{"media":{"uk":"media/uk/radical__gb_1.mp3","us":"media/us/radical__us_1.mp3"},"oxford":{"phon":"ˈrædɪkl","pos":"adjective","senses":[{"en":"relating to the most basic and important parts of something; complete and detailed","cn":"根本的；彻底的；完全的","ex":{"en":"the need for radical changes in education","cn":"对教育进行彻底变革的需要"}},{"en":"new, different and likely to have a great effect","cn":"全新的；不同凡响的","ex":{"en":"radical ideas","cn":"不同凡响的观点"}},{"en":"in favour of extreme and complete political or social change","cn":"激进的；极端的","ex":{"en":"the radical wing of the party","cn":"党内的激进派"}},{"en":"very good","cn":"极好的；很棒的","lab":"North American English, old-fashioned, slang，，，，"},{"en":"a person with radical opinions","cn":"激进分子","ex":{"en":"political radicals","cn":"政治激进分子"},"pos":"noun"},{"en":"a group of atoms that behave as a single unit in a number of compounds","cn":"游离基；自由基","lab":"chemistry","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重大的;根本的;基本的;彻底的","en":"Radical changes and differences are very important and great in degree.","ex":{"en":"The country needs a period of calm without more surges of radical change","cn":"国家需要一段时间的稳定，其间不要再有重大的变革。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"激进的；激进派的","en":"Radical people believe that there should be great changes in society and try to bring about these changes.","ex":{"en":"...threats by left-wing radical groups to disrupt the proceedings.","cn":"来自于左翼激进团体可能破坏会议进程的威胁"}}]},"examples":[{"en":"The new methods are radically different from the old.","cn":"新的方法迥然不同于旧的方法。"},{"en":"the need for radical changes in education","cn":"对教育进行彻底变革的需要"}]},"raised":{"media":{"uk":"media/uk/raised__gb_1.mp3","us":"media/us/raised__us_1.mp3"},"oxford":{"phon":"reɪzd","pos":"adjective","senses":[{"en":"higher than the area around","cn":"凸起的","ex":{"en":"a raised platform","cn":"凸起的平台"}},{"en":"at a higher level than normal","cn":"提高的；升高的","ex":{"en":"the sound of raised voices","cn":"提高嗓门的说话声"}}]},"examples":[{"en":"Smokers often have raised blood pressure.","cn":"吸烟者往往血压高。"},{"en":"the sound of raised voices","cn":"提高嗓门的说话声"}],"base":"raise"},"rational":{"oxford":{"phon":"ˈræʃnəl","pos":"adjective","senses":[{"en":"based on reason rather than emotions","cn":"合理的；理性的；明智的","ex":{"en":"a rational argument/choice/decision","cn":"合理的论点／选择／决定"}},{"en":"able to think clearly and make decisions based on reason rather than emotions","cn":"理智的；清醒的","ex":{"en":"No rational person would ever behave like that.","cn":"头脑清醒的人都不会这样做。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"理性的;合理的","en":"Rational decisions and thoughts are based on reason rather than on emotion.","ex":{"en":"He's asking you to look at both sides of the case and come to a rational decision","cn":"他是要求你看到问题的两面后再作出理性的决定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"理性的;理智的","en":"A rational person is someone who is sensible and is able to make decisions based on intelligent thinking rather than on emotion.","ex":{"en":"Did he come across as a sane rational person?","cn":"他看起来是一个正常而理智的人吗？"}}]},"media":{"uk":"media/uk/rational__gb_1.mp3","us":"media/us/rational__us_1.mp3"},"examples":[{"en":"There is no rational explanation for his actions.","cn":"对他的所作所为无法作出合理的解释。"},{"en":"She argued her case calmly and rationally.","cn":"她冷静而又理智地为她的情况辩解。"}]},"raft":{"media":{"uk":"media/uk/raft__gb_1.mp3","us":"media/us/raft__us_1.mp3"},"oxford":{"phon":"rɑːft","pos":"noun","senses":[{"en":"a flat structure made of pieces of wood tied together and used as a boat or floating platform","cn":"木排；筏"},{"en":"a small boat made of rubber or plastic that is filled with air","cn":"橡皮艇；充气船","ex":{"en":"an inflatable raft","cn":"充气橡皮筏"}},{"en":"a large number or amount of something","cn":"大量；许多","g":"[usually singular]","lab":"informal","ex":{"en":"a whole raft of new proposals","cn":"大量新的提议"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"木排；木筏；筏子","en":"A raft is a floating platform made from large pieces of wood or other materials tied together.","ex":{"en":"...a river trip on bamboo rafts through dense rainforest.","cn":"坐竹筏穿过茂密雨林的河上之旅"}},{"pos":"N-COUNT 可数名词","cn":"充气浮垫；救生筏","en":"A raft is a small rubber or plastic boat that you blow air into to make it float.","ex":{"en":"The crew spent two days and nights in their raft.","cn":"船员在救生筏上呆了两天两夜。"}},{"pos":"N-COUNT 可数名词","cn":"大堆；大量","en":"A raft of people or things is a lot of them.","ex":{"en":"He has surrounded himself with a raft of advisers who are very radical","cn":"他周围聚集了一大群偏激的顾问。"}}]},"examples":[{"en":"a whole raft of new proposals","cn":"大量新的提议"},{"en":"an inflatable raft","cn":"充气橡皮筏"}]},"rank":{"media":{"uk":"media/uk/rank__gb_1.mp3","us":"media/us/rank__us_1.mp3"},"oxford":{"phon":"ræŋk","pos":"noun","senses":[{"en":"the position, especially a high position, that somebody has in a particular organization, society, etc.","cn":"（尤指较高的）地位，级别","g":"[uncountable, countable]","sc":"position in organization/army, etc.","ex":{"en":"She was not used to mixing with people of high social rank.","cn":"她不习惯和社会地位很高的人交往。"}},{"en":"the position that somebody has in the army, navy, police, etc.","cn":"军衔；军阶；警衔","g":"[countable, uncountable]","sc":"position in organization/army, etc.","ex":{"en":"He was soon promoted to the rank of captain.","cn":"他很快被提升至上尉军阶。"}},{"en":"the position of ordinary soldiers rather than officers; the army","cn":"士兵；部队","g":"[plural]","sc":"position in organization/army, etc.","ex":{"en":"He served in the ranks for most of the war.","cn":"战争期间，他大部分时间都在部队服役。"}},{"en":"the degree to which somebody/something is of high quality","cn":"等级；级别","g":"[singular]","sc":"quality","ex":{"en":"a painter of the first rank","cn":"一流的画家"}},{"en":"the members of a particular group or organization","cn":"（团体或组织的）成员","g":"[plural]","sc":"members of group","ex":{"en":"We have a number of international players in our ranks.","cn":"我们的队员中有好几个国际选手。"}},{"en":"a line or row of soldiers, police, etc. standing next to each other","cn":"（警察、士兵等的）队列，行列","g":"[countable]","sc":"line/row","ex":{"en":"They watched as ranks of marching infantry passed the window.","cn":"他们看着步兵列队从窗前走过。"}},{"en":"a line or row of people or things","cn":"排；行；列","g":"[countable]","sc":"line/row","ex":{"en":"massed ranks of spectators","cn":"聚集起来的旁观者的行列"}},{"en":"a number that gives the position of a member of a set of numbers","cn":"普通士兵","g":"[countable]","lab":"statistics","sc":"in statistics"},{"en":"to give somebody/something a particular position on a scale according to quality, importance, success, etc.; to have a position of this kind","cn":"把…分等级；属于某等级","g":"[transitive, intransitive]","lab":"North American English","sc":"give position","ex":{"en":"In most Australian elections, electors are required to rank all candidates.","cn":"在澳大利亚多数选举中，选民须对所有候选人进行排名。"},"pos":"verb"},{"en":"to arrange objects in a line or row","cn":"排列；使排成行","g":"[transitive, usually passive]","sc":"put in line/row","pos":"verb"},{"en":"having a strong unpleasant smell","cn":"难闻的；恶臭的","ex":{"en":"The house was full of the rank smell of urine.","cn":"这屋子里到处有一股尿的臊味。"},"pos":"adjective"},{"en":"very unpleasant","cn":"非常糟糕的","lab":"informal","ex":{"en":"I think the whole situation's pretty rank.","cn":"我认为整个情况很糟糕。"},"pos":"adjective"},{"en":"used to emphasize a particular quality, state, etc.","cn":"（强调质量、状况等）极端的，糟糕的","g":"[only before noun]","ex":{"en":"an example of rank stupidity/hypocrisy","cn":"极端愚蠢／虚伪的例子"},"pos":"adjective"},{"en":"growing too thickly","cn":"疯长的","ex":{"en":"an area overgrown with rank grass and nettles","cn":"长满杂草和荨麻的地区"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"等级;地位;级别","en":"Someone's rank is the position or grade that they have in an organization.","ex":{"en":"He eventually rose to the rank of captain","cn":"他终于升职当上了船长。"}},{"pos":"N-VAR 可变名词","cn":"（尤指社会地位高的）阶级，地位","en":"Someone's rank is the social class, especially the high social class, that they belong to.","ex":{"en":"Each rank of the peerage was represented","cn":"每个贵族阶级都有代表。"}},{"pos":"V-ERG 及物/不及物动词","cn":"给…评级;给…评名次","en":"If an official organization ranks someone or something 1st, 5th, or 50th, for example, they calculate that the person or thing has that position on a scale. You can also say that someone or something ranks 1st, 5th, or 50th, for example.","ex":{"en":"The report ranks the UK 20th out of 22 advanced nations","cn":"报告中把英国排在22个先进国家中的第20位。"}},{"pos":"V-ERG 及物/不及物动词","cn":"列为；位居","en":"If you say that someone or something ranks high or low on a scale or if you rank them high or low, you are saying how good or important you think they are.","ex":{"en":"His prices rank high among those of other contemporary photographers","cn":"在当代摄影师当中，他的要价很高。"}},{"pos":"VERB 动词","cn":"位列；名列","en":"If you say that someone or something ranks with a group of famous people or things, you mean that they are extremely good and should be included in that group.","ex":{"en":"...a performance of heroic calibre that must rank with the most memorable in international rugby","cn":"必被列为国际橄榄球赛中最令人难忘的一场荡气回肠的比赛"}},{"pos":"N-PLURAL 复数名词","cn":"（团体或组织的）全体成员;队伍","en":"The ranks of a group or organization are the people who belong to it.","ex":{"en":"There were some misgivings within the ranks of the media too","cn":"媒体内部也存在一些疑虑。"}},{"pos":"N-PLURAL 复数名词","cn":"普通成员；（尤指军队的）普通士兵","en":"The ranks are the ordinary members of an organization, especially of the armed forces.","ex":{"en":"Top military leaders say there have been reports of demoralization in the ranks","cn":"最高军事指挥说有报告称士兵中出现了士气低落。"}},{"pos":"N-COUNT 可数名词","cn":"（人或物组成的）排，列，行","en":"A rank of people or things is a row of them.","ex":{"en":"Ranks of police in riot gear stood nervously by","cn":"一队队防暴警察紧张待命。"}},{"pos":"N-COUNT 可数名词","cn":"出租汽车候客处","en":"A taxi rank is a place on a city street where taxis park when they are available for hire.","ex":{"en":"The man led the way to the taxi rank","cn":"那人带路来到了出租汽车候客处。"}},{"pos":"ADJ 形容词","cn":"（恶劣品质等）十足的，完全的","en":"You can use rank to emphasize a bad or undesirable quality that exists in an extreme form.","ex":{"en":"He called it 'rank hypocrisy' that the government was now promoting equal rights.","cn":"他把目前政府提倡平等权利的举措称为“彻头彻尾的伪善”。"}},{"pos":"ADJ 形容词","cn":"臭气难闻的；（气味）令人恶心的","en":"You can describe something as rank when it has a strong and unpleasant smell.","ex":{"en":"The kitchen was rank with the smell of drying uniforms.","cn":"厨房内充斥着烘干制服的难闻气味。"}},{"pos":"PHRASE 短语","cn":"（队伍、组织的成员等）违反指令，抗命","en":"If you say that a member of a group or organization breaks ranks, you mean that they disobey the instructions of their group or organization.","ex":{"en":"'Even the President's staunchest supporters have some issues where they simply must break ranks,' says Senator Lott","cn":"“即使是总统最忠实的拥护者在某些事情上也会不听指令，”参议员洛特说。"}},{"pos":"PHRASE 短语","cn":"（在受到批评时）捐弃嫌隙而携手合作，抱成一团","en":"If you say that the members of a group close ranks, you mean that they are supporting each other only because their group is being criticized.","ex":{"en":"Conservative MPs intend to put aside their differences over Europe and close ranks behind the Prime Minister","cn":"保守党下院议员打算暂且搁置他们在欧洲问题上的分歧，团结起来支持首相。"}},{"pos":"PHRASE 短语","cn":"步…后尘；经历（他人）曾经历过的（尤指坏事）","en":"If you experience something, usually something bad, that other people have experienced, you can say that you have joined their ranks .","ex":{"en":"Last month, 370,000 Americans joined the ranks of the unemployed","cn":"上个月，有37万美国人加入了失业者的行列。"}},{"pos":"PHRASE 短语","cn":"成功可能性不大的参赛者","en":"If one of the people in a competition is described as a rank outsider, they are considered to have very little chance of winning.","ex":{"en":"The rank outsiders, Cameroon, beat the defending champions, Argentina, by one goal to nil.","cn":"本不被看好的喀麦隆队却以1比0击败了卫冕冠军阿根廷队。"}},{"pos":"PHRASE 短语","cn":"运用职权，滥用权力（压制他人）","en":"If you say that someone in authority pulls rank, you mean that they unfairly force other people to do what they want because of their higher rank or position.","ex":{"en":"The Captain pulled rank and made his sergeant row the entire way.","cn":"上校倚仗权势让他的中士划船划了一路。"}}]},"examples":[{"en":"This must rank with (= be as good as) the greatest movies ever made.","cn":"这部影片一定可与史上最优秀的影片相媲美。"},{"en":"At the height of her career she ranked second in the world.","cn":"在她事业的顶峰时期，她排名世界第二位。"}]},"rain":{"media":{"uk":"media/uk/rain__gb_1.mp3","us":"media/us/rain__us_1.mp3"},"oxford":{"phon":"reɪn","pos":"noun","senses":[{"en":"water that falls from the sky in separate drops","cn":"雨；雨水","g":"[uncountable, singular]","lab":"British English","ex":{"en":"There will be rain in all parts tomorrow.","cn":"明天，各地区都会有雨。"}},{"en":"the season of heavy continuous rain in tropical countries","cn":"（热带地区的）雨季","g":"[plural]","ex":{"en":"The rains come in September.","cn":"雨季九月份开始。"}},{"en":"a large number of things falling from the sky at the same time","cn":"雨点般降落的东西","g":"[singular]","ex":{"en":"a rain of bullets","cn":"一阵弹雨"}},{"en":"when it rains, water falls from the sky in drops","cn":"下雨","g":"[intransitive]","ex":{"en":"Is it raining?","cn":"下雨了吗？"},"pos":"verb"},{"en":"to fall or to make something fall on somebody/something in large quantities","cn":"（使）大量降落，雨点般落下","g":"[intransitive, transitive]","ex":{"en":"Bombs rained (down) on the city’s streets.","cn":"炸弹雨点儿似的落在这座城市的街道上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"雨；雨水","en":"Rain is water that falls from the clouds in small drops.","ex":{"en":"I hope you didn't get soaked standing out in the rain","cn":"我希望你站在外面没有被雨淋透。"}},{"pos":"N-PLURAL 复数名词","cn":"雨季","en":"In countries where rain only falls in certain seasons, this rain is referred to as the rains .","ex":{"en":"...the spring, when the rains came","cn":"春天，雨季来临时"}},{"pos":"VERB 动词","cn":"下雨；降雨","en":"When rain falls, you can say that it is raining .","ex":{"en":"It rained the whole weekend","cn":"整个周末都在下雨。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）如雨点般落下；（使）大量降下","en":"If someone rains blows, kicks, or bombs on a person or place, the person or place is attacked by many blows, kicks, or bombs. You can also say that blows, kicks, or bombs rain on a person or place.","ex":{"en":"The police, raining blows on rioters and spectators alike, cleared the park","cn":"警察不分闹事者与观众统统一顿猛击，把人们清除出了足球场。"}},{"pos":"N-SING 单数名词","cn":"（从空中落下的）一阵，一连串","en":"A rain of things is a large number of things that fall from the sky at the same time.","ex":{"en":"A rain of stones descended on the police.","cn":"一阵乱石砸向警察。"}},{"pos":"PHRASE 短语","cn":"祸不单行","en":"You can use the expression it never rains but it pours to mean that several unfortunate events often happen at the same time."},{"pos":"PHRASE 短语","cn":"完全康复；完全恢复","en":"If you say that someone is as right as rain, you mean that they are completely well or healthy again, for example when they have recovered from an illness or a shock.","ex":{"en":"You'll be as right as rain as soon as you are back in your own home with your baby.","cn":"你一回家同孩子在一起就会完全没事了。"}},{"pos":"PHRASE 短语","cn":"不管晴天或下雨;风雨无阻","en":"If you say that someone does something rain or shine, you mean that they do it regularly, without being affected by the weather or other circumstances.","ex":{"en":"Frances took her daughter walking every day, rain or shine.","cn":"弗朗西丝无论晴天还是下雨，每天都带女儿去散步。"}},{"pos":"","cn":"","en":"相关词组：rain off rain out"}]},"examples":[{"en":"The volcano erupted, raining hot ash over a wide area.","cn":"火山喷发，将炽热的火山灰洒落在一大片地域上。"},{"en":"He covered his face as the blows rained down on him (= he was hit repeatedly).","cn":"他在遭到雨点般的击打时护住了自己的脸。"}]},"racial":{"oxford":{"phon":"ˈreɪʃl","pos":"adjective","senses":[{"en":"happening or existing between people of different races","cn":"种族的；种族间的","g":"[only before noun]","ex":{"en":"racial hatred/prejudice/tension/violence","cn":"种族仇恨／偏见；种族间的紧张状况／暴力"}},{"en":"connected with a person’s race","cn":"人种的；种族的","g":"[usually before noun]","ex":{"en":"racial minorities","cn":"少数民族"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"种族的；种族间的；人种的","en":"Racial describes things relating to people's race.","ex":{"en":"...the protection of national and racial minorities.","cn":"对少数民族和少数人种的保护"}}]},"media":{"uk":"media/uk/racial__gb_1.mp3","us":"media/us/racial__us_1.mp3"},"examples":[{"en":"They have pledged to end racial discrimination in areas such as employment.","cn":"他们已经保证在诸如就业等方面停止种族歧视。"},{"en":"The attacks were not racially motivated.","cn":"袭击事件不是由种族原因引起的。"}]},"raf":{"oxford":{"phon":"ˌɑːr eɪ ˈef","pos":"abbreviation","senses":[{"en":"Royal Air Force (the British air force)","cn":"（英国）皇家空军","ex":{"en":"He was an RAF pilot.","cn":"他是皇家空军飞行员。"}}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"英国皇家空军","en":"The RAF is the air force of the United Kingdom. RAF is an abbreviation for (缩略=) 'Royal Air Force'.","ex":{"en":"An RAF helicopter rescued the men after the boat began taking in water.","cn":"在船开始进水后，一架英国皇家空军的直升机救起了那些船员。"}}]},"media":{"uk":"media/uk/raf__gb_1.mp3","us":"media/us/raf__us_1.mp3"},"examples":[{"en":"He was an RAF pilot.","cn":"他是皇家空军飞行员。"}]},"rail":{"media":{"img":["media/pic/trains_comp.jpg","media/thumb/freighttrain.jpg"],"uk":"media/uk/rail__gb_1.mp3","us":"media/us/rail__us_1.mp3"},"oxford":{"phon":"reɪl","pos":"noun","senses":[{"en":"a wooden or metal bar placed around something as a barrier or to provide support","cn":"栏杆；扶手；围栏","g":"[countable]","ex":{"en":"She leaned on the ship's rail and gazed out to sea.","cn":"她靠着船上的护栏，凝望大海。"}},{"en":"a bar fixed to the wall for hanging things on","cn":"（固定在墙上用以挂物品的）横杆","g":"[countable]","ex":{"en":"a picture/curtain/towel rail","cn":"挂图画／窗帘／毛巾用的横杆"}},{"en":"each of the two metal bars that form the track that trains run on","cn":"铁轨；轨道","g":"[countable, usually plural]","ex":{"en":"The train thundered along the rails.","cn":"火车沿铁轨呼啸而过。"}},{"en":"railways as a means of transport","cn":"铁路；铁道","g":"[uncountable]","ex":{"en":"to travel by rail","cn":"乘火车"}},{"en":"to complain about something/somebody in a very angry way","cn":"怒斥；责骂；抱怨","lab":"formal","ex":{"en":"She railed against the injustice of it all.","cn":"她大骂此事太不公正。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"横杆；栏杆；扶手","en":"A rail is a horizontal bar attached to posts or fixed round the edge of something as a fence or support.","ex":{"en":"They had to walk across an emergency footbridge, holding onto a rope that served as a rail","cn":"他们必须握着一条绳索充当扶手穿过一条紧急人行天桥。"}},{"pos":"N-COUNT 可数名词","cn":"（挂物用的）横杆，横档","en":"A rail is a horizontal bar that you hang things on.","ex":{"en":"...frocks hanging from a rail","cn":"挂在横杆上的连衣裙"}},{"pos":"N-COUNT 可数名词","cn":"铁轨","en":"Rails are the steel bars which trains run on.","ex":{"en":"The train left the rails but somehow forced its way back onto the line.","cn":"火车脱轨了，但总算设法回到了原来的轨道上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"乘火车（旅行）；用火车（运送）","en":"If you travel or send something by rail, you travel or send it on a train.","ex":{"en":"The president traveled by rail to his home town.","cn":"总统坐火车回到了他的家乡。"}},{"pos":"VERB 动词","cn":"（大声）责骂，呵斥","en":"If you rail against something, you criticize it loudly and angrily.","ex":{"en":"He railed against hypocrisy and greed","cn":"他痛斥伪善和贪婪的行为。"}},{"pos":"PHRASE 短语","cn":"复苏；重振","en":"If something is back on the rails, it is beginning to be successful again after a period when it almost failed.","ex":{"en":"They are keen to get the negotiating process back on the rails","cn":"他们热切希望使谈判重新步入正轨。"}},{"pos":"PHRASE 短语","cn":"（行为）越轨，不规矩","en":"If someone goes off the rails, they start to behave in a way that other people think is unacceptable or very strange, for example they start taking drugs or breaking the law.","ex":{"en":"They've got to do something about these children because clearly they've gone off the rails.","cn":"他们必须得管管这些孩子了，因为他们实在太不像话了。"}}]},"examples":[{"en":"The company has gone badly off the rails in recent years.","cn":"这家公司最近几年已经陷于严重瘫痪。"},{"en":"She leaned on the ship's rail and gazed out to sea.","cn":"她靠着船上的护栏，凝望大海。"}]},"randomly":{"oxford":{"phon":"ˈrændəmli","pos":"adverb","senses":[{"en":"without somebody deciding in advance what is going to happen and without any regular pattern","cn":"随意；随机；胡乱","ex":{"en":"The winning numbers are randomly selected by computer.","cn":"中奖号码由电脑随机选出。"}}]},"media":{"uk":"media/uk/randomly__gb_1.mp3","us":"media/us/randomly__us_1.mp3"},"examples":[{"en":"The winning numbers are randomly selected by computer.","cn":"获奖号码是由电脑随机选取的。"},{"en":"My phone seems to switch itself off randomly.","cn":"我的手机好像随时自动关机。"}]},"rage":{"oxford":{"phon":"reɪdʒ","pos":"noun","senses":[{"en":"a feeling of violent anger that is difficult to control","cn":"暴怒；狂怒","g":"[uncountable, countable]","ex":{"en":"His face was dark with rage.","cn":"他气得面色铁青。"}},{"en":"anger and violent behaviour caused by a particular situation","cn":"（某情况引起的）愤怒，暴力行为","g":"[uncountable]","ex":{"en":"a case of trolley rage in the supermarket","cn":"超市里一起由手推车引起的暴力事件"}},{"en":"to show that you are very angry about something or with somebody, especially by shouting","cn":"发怒；怒斥","g":"[intransitive, transitive]","ex":{"en":"He raged against the injustice of it all.","cn":"这一切不公正使他大发怒火。"},"pos":"verb"},{"en":"to continue in a violent way","cn":"猛烈地继续；激烈进行","g":"[intransitive]","ex":{"en":"The riots raged for three days.","cn":"暴乱持续了三天。"},"pos":"verb"},{"en":"to spread very quickly","cn":"迅速蔓延；快速扩散","g":"[intransitive]","ex":{"en":"Forest fires were raging out of control.","cn":"森林大火正迅速蔓延，无法控制。"},"pos":"verb"},{"en":"to go out and enjoy yourself","cn":"外出玩个痛快；出去作乐","g":"[intransitive]","lab":"Australian English, New Zealand English, slang，，，，","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"狂怒；盛怒","en":"Rage is strong anger that is difficult to control.","ex":{"en":"He was red-cheeked with rage","cn":"他气得满脸通红。"}},{"pos":"VERB 动词","cn":"肆虐；猖獗","en":"You say that something powerful or unpleasant rages when it continues with great force or violence.","ex":{"en":"Train services were halted as the fire raged for more than four hours","cn":"火灾肆虐超过4个小时，期间列车停止了运行。"}},{"pos":"VERB 动词","cn":"发脾气；大怒","en":"If you rage about something, you speak or think very angrily about it.","ex":{"en":"Monroe was on the phone, raging about her mistreatment by the brothers","cn":"门罗正在打电话，怒不可遏地说着她被这几个兄弟虐待的事。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指引发暴力或攻击行为的）暴怒,盛怒","en":"You can refer to the strong anger that someone feels in a particular situation as a particular rage, especially when this results in violent or aggressive behaviour.","ex":{"en":"Cabin crews are reporting up to nine cases of air rage a week.","cn":"乘务人员一周内报告的飞机上闹事行为多达9起。"}},{"pos":"N-SING 单数名词","cn":"风靡一时;非常流行","en":"When something is popular and fashionable, you can say that it is the rage or all the rage .","ex":{"en":"The 1950s look is all the rage at the moment.","cn":"目前，20世纪50年代的装扮正流行。"}}]},"media":{"uk":"media/uk/rage__gb_1.mp3","us":"media/us/rage__us_1.mp3"},"examples":[{"en":"He flies into a rage if you even mention the subject.","cn":"你只要一提起这个话题，他就会暴跳如雷。"},{"en":"a case of trolley rage in the supermarket","cn":"超市里一起由手推车引起的暴力事件"}]},"raining":{"lemma":"rain"},"ranks":{"lemma":"rank"},"rangers":{"oxford":{"phon":"ˈreɪndʒəz","pos":"","senses":[{"en":"a football team from Glasgow, Scotland, with a ground at Ibrox Stadium. It was established in 1873 and has had many successes in Scottish football, including several wins in the Scottish Cup. Its traditional rival in Glasgow is Celtic, which has mainly Roman Catholic supporters, while Rangers has mainly Protestant supporters.","cn":"游骑兵：一支来自苏格兰格拉斯哥的橄榄球队，在伊布罗克斯体育场（Ibrox Stadium）着陆。它成立于1873年，在苏格兰足球中取得了许多成功，包括在苏格兰杯中取得了几项胜利。它在格拉斯哥的传统竞争对手是凯尔特人，主要是罗马天主教的支持者，而流浪者则主要是新教徒的支持者。"}]},"media":{"uk":"media/ldoce/hwd/bre/2/p028-000010240.mp3","us":"media/ldoce/hwd/ame/e/ld5_rangers.mp3"}},"rates":{"lemma":"rate"},"ramped":{"oxford":{"phon":"ræmp","pos":"noun","senses":[{"en":"a slope that joins two parts of a road, path, building, etc. when one is higher than the other","cn":"斜坡；坡道"},{"en":"a road used for driving onto or off a major road such as a motorway or interstate （","cn":"进出高速公路等的）支路，引路"}]}},"rained":{"lemma":"rain"},"ranges":{"lemma":"range"},"railroading":{"lemma":"railroad"},"rarer":{"lemma":"rare"},"rambles":{"lemma":"ramble"},"rains":{"lemma":"rain"},"railed":{"lemma":"rail"},"ranging":{"lemma":"range"},"railways":{"lemma":"railway"},"ransom":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"赎价；赎金","en":"A ransom is the money that has to be paid to someone so that they will set free a person they have kidnapped.","ex":{"en":"Her kidnapper successfully extorted a £75,000 ransom for her release","cn":"绑匪成功地勒索了7.5万英镑才将她释放。"}},{"pos":"VERB 动词","cn":"赎回；赎出","en":"If you ransom someone who has been kidnapped, you pay the money to set them free.","ex":{"en":"The same system was used for ransoming or exchanging captives.","cn":"相同的制度还应用于赎回或交换俘虏。"}},{"pos":"PHRASE 短语","cn":"劫持（某人）勒索金钱;绑票;绑架","en":"If a kidnapper is holding someone to ransom or holding them ransom in British English, or is holding a person for ransom in American English, they keep that person prisoner until they are given what they want.","ex":{"en":"He is charged with kidnapping a businessman last year and holding him for ransom","cn":"他被控于去年绑架了一名商人并勒索钱财。"}},{"pos":"PHRASE 短语","cn":"威胁;胁迫","en":"If you say that someone is holding you to ransom in British English, or holding you for ransom in American English, you mean that they are using their power to try to force you to do something which you do not want to do.","ex":{"en":"Unison and the other unions have the power to hold the Government to ransom.","cn":"公务员工会和其他工会有能力胁迫政府。"}},{"pos":"PHRASE 短语","cn":"一大笔钱;巨款","en":"If you refer to a sum of money as a king's ransom, you are emphasizing that it is very large.","ex":{"en":"...clients happy to pay a king's ransom for a haircut.","cn":"乐意为理发出高价的顾客"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to tell someone that you will hurt them or cause serious problems for them if they do not do what you want","cn":""},{"en":"to try to make someone do what you want by making them feel afraid","cn":""},{"en":"to try to make someone stay away from somewhere or stop doing something by warning or threatening them","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you’re ever kidnapped, you’d probably be worth millions in ransom . Ransom is the money demanded for the release of a captive."}]},"collocations":{"phrases":["VERB + RANSOM hold sb for/to, kidnap sb for She was kidnapped and held for ransom. (figurative) The company refused to be held to ransom by ","RANSOM + NOUN demand, note | money, payment","PREP. for ~ stealing cattle for ransom"]},"media":{"uk":"media/ldoce/hwd/bre/c/ransom_n0205.mp3","us":"media/ldoce/hwd/ame/2/ransom1.mp3"},"examples":[{"en":"The kidnapped children were all ransomed and returned home unharmed.","cn":"被绑架的儿童在赎金交付后均安然回到家中。"},{"en":"The kidnappers demanded a ransom of £50 000 from his family.","cn":"绑架者向他的家人索要赎金 5 万英镑。"}],"oxford":{"phon":"ˈrænsəm","pos":"noun","senses":[{"en":"money that is paid to somebody so that they will set free a person who is being kept as a prisoner by them","cn":"赎金","ex":{"en":"The kidnappers demanded a ransom of £50 000 from his family.","cn":"绑架者向他的家人索要赎金 5 万英镑。"}},{"en":"to pay money to somebody so that they will set free the person that they are keeping as a prisoner","cn":"（为某人）交付赎金","ex":{"en":"The kidnapped children were all ransomed and returned home unharmed.","cn":"被绑架的儿童在赎金交付后均安然回到家中。"},"pos":"verb"}]}},"rapist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"强奸者;强奸犯","en":"A rapist is a man who has raped someone.","ex":{"en":"The convicted murderer and rapist is scheduled to be executed next Friday.","cn":"那名被判有罪的强奸杀人犯定在下周五处决。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who steals things","cn":""},{"en":"someone who steals money or valuable things from a bank, shop etc – used especially when someone sees the person who is stealing","cn":""},{"en":"someone who goes into people’s homes in order to steal","cn":""}]},"collocations":{"phrases":["ADJ. potential, would-be | convicted | multiple, serial The serial rapist has struck again.","RAPIST + VERB attack (sb), strike"]},"media":{"uk":"media/ldoce/hwd/bre/4/rapist0205.mp3","us":"media/ldoce/hwd/ame/2/rapist.mp3"},"examples":[{"en":"She later found out that he was a convicted rapist.","cn":"她后来发现他是个已被定罪的强奸犯。"}],"oxford":{"phon":"ˈreɪpɪst","pos":"noun","senses":[{"en":"a person who forces somebody to have sex when they do not want to (= rapes them)","cn":"强奸犯；强奸者","ex":{"en":"The serial rapist has struck again.","cn":"连环强奸犯又作案了。"}}]}},"rainfall":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（降）雨量","en":"Rainfall is the amount of rain that falls in a place during a particular period.","ex":{"en":"There have been four years of below average rainfall.","cn":"已经有4年降雨量低于平均值了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of rain that falls on an area in a particular period of time","cn":"雨量"}]},"collocations":{"phrases":["ADJ. abundant, excessive, heavy, high There have been heavy rainfalls this month. | low | moderate | normal | good, poor We need a good rain","VERB + RAINFALL have The area has a high annual rainfall. | measure Her work includes measuring the local rainfall."]},"media":{"uk":"media/ldoce/hwd/bre/9/rainfall0205.mp3","us":"media/ldoce/hwd/ame/7/rainfall.mp3"},"examples":[{"en":"There has been below average rainfall this month.","cn":"这个月的降雨低于平均降雨量。"},{"en":"an average annual rainfall of 10 cm * 10","cn":"厘米的年平均降雨量"}],"oxford":{"phon":"ˈreɪnfɔːl","pos":"noun","senses":[{"en":"the total amount of rain that falls in a particular area in a particular amount of time; an occasion when rain falls","cn":"降雨量；下雨","ex":{"en":"There has been below average rainfall this month.","cn":"这个月的降雨低于平均降雨量。"}}]}},"raffle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"抽奖;抽彩","en":"A raffle is a competition in which you buy tickets with numbers on them. Afterwards some numbers are chosen, and if your ticket has one of these numbers on it, you win a prize.","ex":{"en":"Any more raffle tickets? Twenty-five pence each or five for a pound.","cn":"还有要买奖券的吗？每张25便士，1英镑5张。"}},{"pos":"VERB 动词","cn":"抽奖赠送（货品）","en":"If someone raffles something, they give it as a prize in a raffle.","ex":{"en":"During each show we will be raffling a fabulous prize.","cn":"每场表演期间，我们将以抽彩方法送出大奖。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a competition or game in which people buy numbered tickets and can win prizes","cn":"兑奖售物（活动）﹐抽彩"},{"en":"to offer something as a prize in a raffle 〔","cn":"在兑奖售物活动中〕提供…作为奖品"}]},"collocations":{"phrases":["ADJ. charity","VERB + RAFFLE have, hold, organize, run | enter | win | draw The club secretary will now draw the raffle.","RAFFLE + NOUN ticket the winning raffle ticket | prize","PREP. in a/the ~ I won a bottle of wine in the office Christmas raffle. | ~ for He's organizing a raffle for the school playground appeal fu"]},"media":{"uk":"media/ldoce/hwd/bre/8/raffle_n0205.mp3","us":"media/ldoce/hwd/ame/d/raffle1.mp3"},"examples":[{"en":"a woman selling raffle tickets","cn":"一位卖奖券的妇女"}],"oxford":{"phon":"ˈræfl","pos":"noun","senses":[{"en":"a way of making money for a particular project or organization. People buy tickets with numbers on them and some of these numbers are later chosen to win prizes.","cn":"抽彩","ex":{"en":"raffle prizes/tickets","cn":"抽奖奖品/门票"}},{"en":"to give something as a prize in a raffle","cn":"抽彩而奖以（物品）","ex":{"en":"The toys will be raffled for charity.","cn":"这些玩具将用于慈善抽奖。"},"pos":"verb"}]}},"rating":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"评价;评级","en":"A rating of something is a score or measurement of how good or popular it is.","ex":{"en":"...a value-for-money rating of ten out of ten","cn":"被评定为100%物有所值"}},{"pos":"N-PLURAL 复数名词","cn":"（电视节目的）收视率","en":"The ratings are the statistics published each week which show how popular each television programme is.","ex":{"en":"Eurocops was beaten in the ratings on Channel 4 by Kate and Allie, Hill Street Blues and St Elsewhere","cn":"在第4频道的收视率调查中《欧洲警察》被《凯特和阿莉》、《希尔街的布鲁斯》和《何方神圣》打败。"}},{"pos":"N-COUNT 可数名词","cn":"水手;普通船员","en":"Ratings are the sailors in some national navies who are not officers or who have no rank."},{"pos":"N-COUNT 可数名词","cn":"（军队的）军阶，级别","en":"The rating of a member of the armed forces is the level they have achieved, according to their job or the skills they have."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a level on a scale that shows how good, important, popular etc someone or something is","cn":"等级﹐程度"},{"en":"a list that shows which films, television programmes etc are the most popular 〔","cn":"电影﹑电视节目等的〕收视率排行榜"},{"en":"a letter that shows whether or not a film is suitable for children 〔","cn":"标示电影是否适合儿童的〕级别"}]},"collocations":{"phrases":["ADJ. high, top | low, poor | overall The overall performance rating puts the new model well ahead of its main rivals. | approval, opinion po","VERB + RATING have | assign (sb/sth), give (sb/sth) | achieve, earn, get, receive, score The university scored a top rating among students. ","RATING + VERB climb, improve, rise, rocket, soar The president's ratings have suddenly rocketed. | fall","RATING + NOUN scale, system","PREP. in a/the ~ a drop of 50 points in her personal rating | ~ for The resort got a low rating for children's facilities. | ~ on The judges","ADJ. good | poor | audience, TV","VERB + RATING get, have At this stage the series was getting good ratings.","RATING + VERB go up, improve, pick up, shoot up, soar The ratings went shooting up overnight. | dip, fall, go down The programme's ratings h"]},"media":{"uk":"media/ldoce/hwd/bre/e/rating0205.mp3","us":"media/ldoce/hwd/ame/1/rating.mp3"},"examples":[{"en":"The poll gave a popular approval rating of 39% for the President.","cn":"民意调查表明民众对总统的支持率为 39%。"},{"en":"The film was given a 15 rating by British censors.","cn":"英国审查员将这部电影定为 15 岁以上级。"}],"oxford":{"phon":"ˈreɪtɪŋ","pos":"noun","senses":[{"en":"a measurement of how good, popular, important, etc. somebody/something is, especially in relation to other people or things","cn":"等级；级别","g":"[countable]","ex":{"en":"Education has been given a high-priority rating by the new administration.","cn":"新一届政府将教育放在了高度优先的地位。"}},{"en":"a set of figures that show how many people watch or listen to a particular television or radio programme, used to show how popular a programme is","cn":"收视率；收听率","g":"[plural]","lab":"British English","ex":{"en":"The show has gone up in the ratings.","cn":"这个节目的收视率上升了。"}},{"en":"a number or letter that shows which groups of people a particular film is suitable for","cn":"表示电影分级的数字（或字母）；电影的等级","g":"[countable]","ex":{"en":"The film was given a 15 rating by British censors.","cn":"英国审查员将这部电影定为 15 岁以上级。"}},{"en":"a sailor in the navy who is not an officer","cn":"海军士兵；水手","g":"[countable]","lab":"British English"}]}},"radar":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"雷达;无线电定位装置","en":"Radar is a way of discovering the position or speed of objects such as aircraft or ships when they cannot be seen, by using radio signals.","ex":{"en":"Pilots complained that the radars in the Mirages malfunctioned during conditions of high humidity","cn":"飞行员抱怨说在高湿度条件下，“幻影”战斗机上的雷达出现了故障。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that uses radio waves to find the position of things and watch their movement","cn":"雷达"},{"en":"if something is on your radar, you have noticed it and are giving it some attention","cn":"受到某人关注/受到关注"},{"en":"to not be noticed by someone","cn":"没被某人注意/没被注意"}]},"vocab":{"pos":"n","senses":[{"en":"Radar is a system for locating objects by bouncing radio waves off of them. Air traffic controllers use radar to keep track of exactly where airplanes are."}]},"collocations":{"phrases":["ADJ. enemy, police","VERB + RADAR be equipped with","RADAR + NOUN operator | screen | beam, signal | equipment, scanner, station, system, transmitter","PREP. by ~ navigating by radar | on ~ The submarine is impossible to detect on radar."]},"media":{"uk":"media/ldoce/hwd/bre/e/radar0205.mp3","us":"media/ldoce/hwd/ame/4/radar.mp3"},"examples":[{"en":"Experts say a lot of corporate crime stays under the radar.","cn":"专家说许多公司犯罪还没有为人所注意到。"},{"en":"They located the ship by radar.","cn":"他们通过雷达确定了船只的位置。"}],"oxford":{"phon":"ˈreɪdɑː(r)","pos":"noun","senses":[{"en":"a system that uses radio waves to find the position and movement of objects, for example planes and ships, when they cannot be seen","cn":"雷达","ex":{"en":"They located the ship by radar.","cn":"他们通过雷达确定了船只的位置。"}}]}},"ram":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"随机存储器;内存","en":"RAM is the part of a computer in which information is stored while you are using it. RAM is an abbreviation for (缩略=) 'Random Access Memory'.","ex":{"en":"...a PC with 256k RAM minimum","cn":"带有最小256K内存的个人计算机"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit another vehicle, a tree, the ground etc, with a lot of force, causing a lot of damage","cn":""},{"en":"to move into something quickly and with force","cn":""},{"en":"if two cars, trains, planes etc collide, they hit each other, especially when they are moving in opposite directions","cn":""}]},"collocations":{"phrases":["ADV. hard | deliberately","PREP. into He deliberately rammed his truck into the back of the one in front."]},"media":{"img":["media/ldoce/img/ram.jpg"],"uk":"media/ldoce/hwd/bre/4/ram0205.mp3","us":"media/ldoce/hwd/ame/8/ram1.mp3"},"examples":[{"en":"256 megabytes of RAM * 256","cn":"兆的内存"},{"en":"256 megabytes of RAM","cn":""}],"oxford":{"phon":"ræm","pos":"verb","senses":[{"en":"to drive into or hit another vehicle, ship, etc. with force, sometimes deliberately","cn":"和…相撞；撞击","ex":{"en":"Two passengers were injured when their taxi was rammed from behind by a bus.","cn":"公共汽车从后面撞来，出租车上的两位乘客受了伤。"}},{"en":"to push something somewhere with force","cn":"塞进；挤进","lab":"figurative","ex":{"en":"She rammed the key into the lock.","cn":"她将钥匙塞进锁眼。"}},{"en":"a male sheep","cn":"公羊","pos":"noun"},{"en":"a part in a machine that is used for hitting something very hard or for lifting or moving things","cn":"夯锤；撞击装置","ex":{"en":"hydraulic rams","cn":"水力夯锤"},"pos":"noun"},{"en":"computer memory in which data can be changed or removed and can be looked at in any order (the abbreviation for ‘random-access memory’)","cn":"随机（存取）存储器，随机存取内存（全写为 random-access memory）","ex":{"en":"16 gigabytes of RAM","cn":"16G 内存"},"pos":"noun"}]}},"rationing":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（食物等的）配给机制","en":"Rationing is the system of limiting the amount of food, water, petrol, or other necessary substances that each person is allowed to have or buy when there is not enough of them.","ex":{"en":"The municipal authorities here are preparing for food rationing.","cn":"这里的市政当局正准备实施食物配给制度。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when the amount of food, petrol etc that people are allowed to have is limited by the government","cn":"定量配给政策﹔配给制"},{"en":"fuel/clothes/food etc rationing News of bread rationing created panic buying.","cn":"面包将定量配给的消息引发了恐慌性购买。"}]},"vocab":{"pos":"n","senses":[{"en":"Rationing is carefully controlling the amount of something that people use. During World War Two, Americans participated in the rationing of food, gasoline, and other materials."}]},"collocations":{"phrases":["ADJ. strict | bread, credit, food, fuel, petrol, etc. | wartime","VERB + RATIONING have | bring in, introduce The government introduced meat rationing in May. | end","RATIONING + VERB be in force, exist","RATIONING + NOUN system","PREP. ~ of Strict rationing of basic foodstuffs was still in force by the end of the year."]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41rationing.mp3","us":"media/ldoce/hwd/ame/5/ld41rationing.mp3"},"oxford":{"phon":"ˈræʃənɪŋ","pos":"noun","senses":[{"en":"the policy of limiting the amount of food, fuel, etc. that people are allowed to have when there is not enough for everyone to have as much as they want","cn":"定量配给政策；配给制","ex":{"en":"The government may have to introduce water rationing.","cn":"政府可能不得不实行配水。"}}]},"base":"ration"},"rapport":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"和睦;友善;亲近","en":"If two people or groups have a rapport, they have a good relationship in which they are able to understand each other's ideas or feelings very well.","ex":{"en":"He said he wanted 'to establish a rapport with the Indian people'","cn":"他说他想“同印度人民建立友好关系”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the way that two people or groups feel about each other and behave towards each other","cn":""},{"en":"the public relationship between groups, organizations, or countries, especially when this affects how well they work together","cn":""},{"en":"a strong relationship between two people, organizations, or countries, especially when they have responsibilities towards each other or official agreements with each other","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Rapport is a good sense of understanding and trust. If you have good rapport with your neighbors, they won't mind if you kick your ball onto their property every now and then."}]},"collocations":{"phrases":["ADJ. close, easy, good, great, tremendous | personal | instant","VERB + RAPPORT build, develop, establish | enjoy, have | feel","PREP. ~ between She felt an instant rapport between them | ~ with He had enjoyed a personal rapport with the former president."]},"media":{"uk":"media/ldoce/hwd/bre/2/rapport0205.mp3","us":"media/ldoce/hwd/ame/6/rapport.mp3"},"examples":[{"en":"She understood the importance of establishing a close rapport with clients.","cn":"她懂得与客户建立密切和谐的关系的重要性。"}],"oxford":{"phon":"ræˈpɔː(r)","pos":"noun","senses":[{"en":"a friendly relationship in which people understand each other very well","cn":"亲善；融洽；和谐","ex":{"en":"She understood the importance of establishing a close rapport with clients.","cn":"她懂得与客户建立密切和谐的关系的重要性。"}}]}},"raid":{"collins":{"senses":[{"pos":"VERB 动词","cn":"突袭;突击","en":"When soldiers raid a place, they make a sudden armed attack against it, with the aim of causing damage rather than occupying any of the enemy's land.","ex":{"en":"The guerrillas raided banks and destroyed a police barracks and an electricity substation.","cn":"游击队突袭了银行，摧毁了一处警察驻地和一个变电站。"}},{"pos":"VERB 动词","cn":"（警察）突击搜捕，搜查","en":"If the police raid a building, they enter it suddenly and by force in order to look for dangerous criminals or for evidence of something illegal, such as drugs or weapons.","ex":{"en":"Fraud squad officers raided the firm's offices.","cn":"反欺诈小组的工作人员突击搜查了这家公司的办公室。"}},{"pos":"VERB 动词","cn":"（入室）抢劫；打劫","en":"If someone raids a building or place, they enter it by force in order to steal something.","ex":{"en":"A 19-year-old man has been found guilty of raiding a bank.","cn":"一个19岁的男子被判抢劫银行罪。"}},{"pos":"VERB 动词","cn":"扫荡（冰箱、食品柜等处）的食物","en":"If you raid the fridge or the larder, you take food from it to eat instead of a meal or in between meals.","ex":{"en":"She made her way to the kitchen to raid the fridge.","cn":"她走向厨房去扫荡冰箱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an act of using weapons against an enemy in a war","cn":""},{"en":"an occasion when an army enters a country and tries to take control of it","cn":""},{"en":"a short attack on a place by soldiers or planes, intended to cause damage but not take control","cn":""}]},"collocations":{"phrases":["ADJ. daring | destructive, heavy, major | punitive, retaliatory, revenge | dawn, daylight, night | border, cross-border | air, bombing | com","VERB + RAID carry out, conduct, make bombers carrying out daylight raids over northern France | launch, mount, stage | lead sb in | suffer","PREP. during/in a/the ~ Five civilians died in the raid. | on a/the ~ He led his men on a cross-border raid. | ~ against The raids against N","ADJ. bank, post office, shop | armed, smash-and-grab | dawn, daylight, night | daring","VERB + RAID plan | carry out | foil Two customers have foiled a smash-and-grab raid on a local shop.","PREP. during/in a/the ~ the jewels stolen in the raid | ~ on She was shot during an armed raid on a security van. 3 surprise visit by the po","ADJ. dawn, early morning | police | drug/drugs","VERB + RAID carry out, launch, stage Police staged an early morning raid on the premises."]},"media":{"uk":"media/ldoce/hwd/bre/5/raid_n0205.mp3","us":"media/ldoce/hwd/ame/4/raid1.mp3"},"examples":[{"en":"Many treasures were lost when the tombs were raided in the last century.","cn":"上世纪这些坟墓遭到偷盗，很多财宝都失踪了。"},{"en":"They were arrested during a dawn raid.","cn":"在一次清晨的突击搜查中，他们都被捕了。"}],"oxford":{"phon":"reɪd","pos":"noun","senses":[{"en":"a short surprise attack on an enemy by soldiers, ships or aircraft","cn":"突然袭击","ex":{"en":"to conduct/launch a raid","cn":"发动突袭"}},{"en":"a surprise visit by the police looking for criminals or for illegal goods or drugs","cn":"突击检查；突然搜查","ex":{"en":"They were arrested during a dawn raid.","cn":"在一次清晨的突击搜查中，他们都被捕了。"}},{"en":"an attack on a building, etc. in order to commit a crime","cn":"抢劫；打劫","ex":{"en":"an armed bank raid","cn":"一起持械抢劫银行案"}},{"en":"to visit a person or place without warning to look for criminals, illegal goods, drugs, etc.","cn":"突击搜捕；突然搜查","ex":{"en":"The house was raided in the early hours.","cn":"房子在凌晨遭到袭击。"},"pos":"verb"},{"en":"to attack a place without warning","cn":"突袭；偷袭","ex":{"en":"Villages along the border are regularly raided.","cn":"边境附近的村庄经常遭受突袭。"},"pos":"verb"},{"en":"to enter a place, usually using force, and steal from it","cn":"劫掠；打劫","lab":"humorous","ex":{"en":"Many treasures were lost when the tombs were raided in the last century.","cn":"上世纪这些坟墓遭到偷盗，很多财宝都失踪了。"},"pos":"verb"}]}},"ration":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"定量;配给量","en":"When there is not enough of something, your ration of it is the amount that you are allowed to have.","ex":{"en":"The meat ration was down to one pound per person per week","cn":"肉的配给量降到了每人每周一磅。"}},{"pos":"VERB 动词","cn":"（通常指由于紧缺）配给，定量供应","en":"When something is rationed by a person or government, you are only allowed to have a limited amount of it, usually because there is not enough of it.","ex":{"en":"Staples such as bread, rice and tea are already being rationed","cn":"面包、大米和茶叶等日常必需品已实行配给。"}},{"pos":"N-PLURAL 复数名词","cn":"（给灾民或士兵的）给养，口粮","en":"Rations are the food which is given to people who do not have enough food or to soldiers.","ex":{"en":"Aid officials said that the first emergency food rations of wheat and oil were handed out here last month","cn":"救助官员说第一批紧急援助的小麦和食用油是上月发放到这里的。"}},{"pos":"N-COUNT 可数名词","cn":"通常的量;定额","en":"Your ration of something is the amount of it that you normally have.","ex":{"en":"...after consuming his ration of junk food and two cigarettes.","cn":"他像往常那样吃完垃圾食品、吸了两根烟后"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fixed amount of something that people are allowed to have when there is not enough, for example during a war 〔","cn":"某物在短缺时的〕配给量﹐定量配给"},{"en":"a fixed amount of food given to a soldier or member of a group","cn":"口粮配给﹐定量口粮"},{"en":"an amount of something that you think is reasonable or normal","cn":"合理[正常]的量"}]},"vocab":{"pos":"n v","senses":[{"en":"When you ration your supplies, you dole them out a little at a time. A ration is also a wartime military meal, or the portion of food that someone is allowed in times of scarcity."}]},"collocations":{"phrases":["ADJ. daily, monthly | double, entire, extra, full Pregnant women received a double ration of milk. | meagre The refugees queued up for their","VERB + RATION give sb, hand out, provide (sb with) | get, receive | consume, have, use up You've had your ration of sweets for the day! | cu","RATION + NOUN book, card, coupon","PREP. on a/the ~ living on starvation rations | ~ of our daily ration of bread"]},"media":{"uk":"media/ldoce/hwd/bre/e/ration_n0205.mp3","us":"media/ldoce/hwd/ame/9/ration1.mp3"},"examples":[{"en":"I've had my ration of problems for one day — you deal with it!","cn":"我手头的问题已经够我忙活一天的了，你来处理这件事吧！"},{"en":"We're on short rations (= allowed less than usual) until fresh supplies arrive.","cn":"在新的补给到达之前，我们的口粮定量不足。"}],"oxford":{"phon":"ˈræʃn","pos":"noun","senses":[{"en":"a fixed amount of food, fuel, etc. that you are officially allowed to have when there is not enough for everyone to have as much as they want, for example during a war","cn":"（食品、燃料等短缺时的）配给量，定量","g":"[countable]","ex":{"en":"the weekly butter ration","cn":"每周的黄油配给量"}},{"en":"a fixed amount of food given regularly to a soldier or to somebody who is in a place where there is not much food available","cn":"（给战士或食品短缺地区的人提供的）定量口粮","g":"[plural]","ex":{"en":"We're on short rations (= allowed less than usual) until fresh supplies arrive.","cn":"在新的补给到达之前，我们的口粮定量不足。"}},{"en":"an amount of something that is thought to be normal or fair","cn":"正常量；合理的量","g":"[singular]","ex":{"en":"As part of the diet, allow yourself a small daily ration of sugar.","cn":"作为饮食的一部分，每天可以摄入少量的糖。"}},{"en":"to limit the amount of something that somebody is allowed to have, especially because there is not enough of it available","cn":"限定…的量；定量供应；配给","ex":{"en":"Eggs were rationed during the war.","cn":"战争期间，鸡蛋限量供应。"},"pos":"verb"}]}},"racism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"种族主义；种族歧视","en":"Racism is the belief that people of some races are inferior to others, and the behaviour which is the result of this belief.","ex":{"en":"There is a feeling among some black people that the level of racism is declining.","cn":"一些黑人感到种族歧视的程度在下降。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when people do not like or trust someone who is different from them, for example because they belong to a different race, country, or religion","cn":""},{"en":"the belief that people of your race are naturally better, more intelligent etc than people of other races, especially when this leads to unfair treatment, hatred, and violence","cn":""},{"en":"prejudiced attitudes and unfair behaviour towards people who belong to a particular sex. Sexism is usually used about unfair treatment of women, but can be used about treatment of and attitudes towards men","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Racism is the practice of discriminating against people based on their race, national or ethnic background. Although old prejudices often live on, most people will agree that racism is unacceptable."}]},"collocations":{"phrases":["ADJ. blatant, overt I was shocked by the blatant racism of his remarks. | rampant Racism is rampant in the armed forces. | institutional, in","VERB + RACISM be a victim of, experience Many immigrants have experienced racism. | combat, fight (against), stamp out measures to combat ra","PREP. against ~ the fight against racism","PHRASES a form of racism"]},"media":{"uk":"media/ldoce/hwd/bre/0/racism0205.mp3","us":"media/ldoce/hwd/ame/a/racism.mp3"},"examples":[{"en":"He's a racist.","cn":"他是个种族主义者。"},{"en":"racist attitudes/attacks/remarks","cn":"种族主义的态度/攻击/言论"}],"oxford":{"phon":"ˈreɪsɪzəm","pos":"noun","senses":[{"en":"the unfair treatment of people who belong to a different race; violent behaviour towards them","cn":"种族歧视；种族迫害","lab":"British English","ex":{"en":"a victim of racism","cn":"种族歧视的受害者"}},{"en":"the belief that there are different races of people with different characteristics and abilities, and that some races are better than others; a general belief about a whole group of people based only on their race","cn":"种族主义；种族偏见","ex":{"en":"irrational racism","cn":"非理性的种族主义"}}]}},"ray":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"光线；光束","en":"Rays of light are narrow beams of light.","ex":{"en":"...the first rays of light spread over the horizon","cn":"地平线上出现的第一缕曙光"}},{"pos":"N-COUNT 可数名词","cn":"一丝，一线（希望、慰藉等）","en":"A ray of hope, comfort, or other positive quality is a small amount of it that you welcome because it makes a bad situation seem less bad.","ex":{"en":"They could provide a ray of hope amid the general business and economic gloom","cn":"在普遍的商业和经济低潮中，他们能带来一线希望。"}},{"pos":"N-COUNT 可数名词","cn":"鳐;魟","en":"A ray is a fairly large sea fish which has a flat body, eyes on the top of its body, and a long tail."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this to say that there is natural daylight, so that you can see easily enough to do something","cn":""},{"en":"the natural light of day","cn":""},{"en":"the light from the sun","cn":""}]},"collocations":{"phrases":["ADJ. powerful | bright | harmful | dying, last the dying rays of a winter sun | cathode, cosmic, gamma, heat, infrared, light, ultraviolet, ","VERB + RAY emit, give off, send out gamma rays given off by plutonium | expose sb/sth to | block, filter out, protect/shield sb/sth from cre","RAY + VERB filter through sth, pass through sth, penetrate sth, travel the moon's rays filtering through the trees | hit sth When the sun's ","PREP. in the ~s of a stream sparkling in the rays of the June sun","PHRASES a ray of light/sunlight/sunshine, the rays of the sun"]},"media":{"uk":"media/ldoce/hwd/bre/7/ray0205.mp3","us":"media/ldoce/hwd/ame/e/ray1.mp3"},"examples":[{"en":"The windows were shining in the reflected rays of the setting sun.","cn":"窗户上闪耀着落日的余晖。"},{"en":"There was just one small ray of hope.","cn":"只有一丝希望。"}],"oxford":{"phon":"reɪ","pos":"noun","senses":[{"en":"a narrow line of light, heat or other energy","cn":"光线；（热或其他能量的）射线","ex":{"en":"The last of the sun's rays shone on the grass.","cn":"最后一缕阳光照在草地上。"}},{"en":"a small amount of something good or of something that you are hoping for","cn":"（好事或所希望事物的）一点，少量","ex":{"en":"There was just one small ray of hope.","cn":"只有一线希望。"}},{"en":"a sea fish with a large broad flat body and a long tail, that is used for food","cn":"鳐（扁体长尾，可食用）"},{"en":"the second note of a major scale","cn":"大调音阶的第 2 音","lab":"music"},{"en":"a first name for boys, short for Raymond","cn":"雷（男子名，Raymond 缩写）","pos":""}]}},"radiation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"辐射物；放射物","en":"Radiation consists of very small particles of a radioactive substance. Large amounts of radiation can cause illness and death.","ex":{"en":"They suffer from health problems and fear the long term effects of radiation","cn":"他们遭受着健康问题的困扰并且害怕辐射的长期影响。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"辐射能;放射能;（尤指）热能","en":"Radiation is energy, especially heat, that comes from a particular source.","ex":{"en":"The satellite will study energy radiation from stars.","cn":"这颗人造卫星将用来研究恒星的能量辐射。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a form of energy that comes especially from nuclear reactions, which in large amounts is very harmful to living things","cn":"辐射﹔〔尤指〕核辐射"},{"en":"energy in the form of heat or light that is sent out as waves that you cannot see 〔","cn":"热能或光能的〕辐射"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"Radiation is energy transmitted in waves or a stream of particles. The first thing you think of as radiation is probably X-rays, but what cooks your food in the microwave oven is also radiation ."}]},"collocations":{"phrases":["ADJ. background | low-level | harmful | electromagnetic, gravitational, infrared, microwave, nuclear, solar, thermal, ultraviolet","QUANT. dose Patients receive high doses of radiation during cancer treatment.","VERB + RADIATION emit, give off | absorb The ozone layer absorbs solar radiation. | measure, monitor | expose sb to Nuclear testing has expo","RADIATION + NOUN sickness | leak | dose, level | exposure | therapy","PREP. ~ from radiation from computer screens"]},"media":{"uk":"media/ldoce/hwd/bre/4/radiation0205.mp3","us":"media/ldoce/hwd/ame/a/radiation.mp3"},"examples":[{"en":"the link between exposure to radiation and childhood cancer","cn":"接触辐射与儿童恶性肿瘤之间的联系"},{"en":"high levels/doses of radiation that damage cells","cn":"损害细胞的高强度辐射"}],"oxford":{"phon":"ˌreɪdiˈeɪʃn","pos":"noun","senses":[{"en":"powerful and very dangerous rays that are sent out from radioactive substances","cn":"辐射；放射线","g":"[uncountable, countable]","ex":{"en":"high levels/doses of radiation that damage cells","cn":"损害细胞的高强度辐射"}},{"en":"heat, energy, etc. that is sent out in the form of rays","cn":"辐射的热（或能量等）","g":"[uncountable]","ex":{"en":"ultraviolet radiation","cn":"紫外线辐射"}},{"en":"the treatment of cancer and other diseases using radiation","cn":"放射疗法","g":"[uncountable]"}]}},"raspberry":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"悬钩子;覆盆子;木莓;山莓","en":"Raspberries are small, soft, red fruit that grow on bushes."},{"pos":"N-COUNT 可数名词","cn":"（表示轻蔑的）吐舌声，呸声","en":"If you blow a raspberry, you make a sound by putting your tongue out and blowing, in order to insult someone.","ex":{"en":"He blows a raspberry down the telephone line and hangs up","cn":"他对着电话呸了一声，然后挂断了。"}},{"pos":"N-COUNT 可数名词","cn":"痛斥;厉声责备","en":"If you blow a raspberry at someone or something, you reject them completely or criticize them severely.","ex":{"en":"...a time to blow a modest raspberry at politics","cn":"对政治稍加指责的时期"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft sweet red berry, or the bush that this berry grows on","cn":"悬钩子﹐覆盆子﹐山莓"},{"en":"a rude sound that you make by putting your tongue out and blowing 〔","cn":"吐舌并吹气而发出的〕呸声"}]},"collocations":{"phrases":["QUANT. punnet I bought a punnet of fresh raspberries.","RASPBERRY + NOUN cane rows of raspberry canes •"]},"media":{"img":["media/ldoce/img/raspberries.jpg","media/thumb/raspberry.jpg"],"uk":"media/ldoce/hwd/bre/b/raspberry0205.mp3","us":"media/ldoce/hwd/ame/5/raspberry.mp3"},"examples":[{"en":"to blow a raspberry at sb","cn":"对某人发出嘘声"},{"en":"raspberry jam","cn":"山莓酱"}],"oxford":{"phon":"ˈrɑːzbəri","pos":"noun","senses":[{"en":"a small, dark red soft fruit that grows on bushes","cn":"覆盆子；山莓；悬钩子","ex":{"en":"raspberry jam","cn":"山莓酱"}},{"en":"a rude sound made by sticking out the tongue and blowing","cn":"（将舌头伸出并吹气而发出的粗鲁的声音）呸声，嘘声","lab":"North American English also","ex":{"en":"to blow a raspberry at somebody","cn":"对某人发出嘘声"}}]}},"rap":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"说唱音乐（一种音乐形式）","en":"Rap is a type of music in which the words are not sung but are spoken in a rapid, rhythmic way.","ex":{"en":"For some people, rap — the music of the hip-hop generation — is just so much noise","cn":"对某些人来说，说唱乐——嘻哈一族的音乐——简直就是噪音。"}},{"pos":"VERB 动词","cn":"表演说唱音乐;说唱","en":"Someone who raps performs rap music.","ex":{"en":"...the unexpected pleasure of hearing the Kids not only rap but even sing","cn":"听到Kids组合不仅表演说唱音乐还唱了歌的意外惊喜"}},{"pos":"N-COUNT 可数名词","cn":"用说唱风格表演的音乐;说唱音乐中的歌词","en":"A rap is a piece of music performed in rap style, or the words that are used in it.","ex":{"en":"Every member contributes to the rap, singing either solo or as part of a rap chorus.","cn":"每个成员都参与到说唱中来，或者独唱，或者表演说唱乐中的和声部分。"}},{"pos":"VERB 动词","cn":"急拍；快敲","en":"If you rap on something or rap it, you hit it with a series of quick blows.","ex":{"en":"Mary Ann turned and rapped on Simon's door.","cn":"玛莉·安转身急促地敲了敲西蒙家的门。"}},{"pos":"N-COUNT 可数名词","cn":"罪名；刑事责任","en":"A rap is a statement in a court of law that someone has committed a particular crime, or the punishment for committing it.","ex":{"en":"You'll be facing a Federal rap for aiding and abetting an escaped convict.","cn":"因涉嫌协助和教唆越狱囚犯，你将面临联邦指控。"}},{"pos":"N-COUNT 可数名词","cn":"批评;责备;训斥","en":"A rap is an act of criticizing or blaming someone.","ex":{"en":"FA chiefs could still face a rap and a possible fine","cn":"足协高层可能还要受到训诫并被处以罚款。"}},{"pos":"VERB 动词","cn":"责备;训斥","en":"If you rap someone for something, you criticize or blame them for it.","ex":{"en":"Water industry chiefs were rapped yesterday for failing their customers","cn":"昨天，水利行业的头头们因为怠慢客户而受到批评。"}},{"pos":"N-SING 单数名词","cn":"名气;（常指并不符合实情的）坏名声","en":"The rap about someone or something is their reputation, often a bad reputation which they do not deserve.","ex":{"en":"The rap against Conn was that he was far too reckless","cn":"科恩被人们认为做事太不计后果。"}},{"pos":"VERB 动词","cn":"闲聊；交谈","en":"If you rap with someone about something, you talk about it in a relaxed or informal way.","ex":{"en":"Today we are going to rap about relationships.","cn":"今天我们要聊聊关系的问题。"}},{"pos":"PHRASE 短语","cn":"训斥；责备；指责","en":"If someone in authority raps your knuckles or raps you on the knuckles, they criticize you or blame you for doing something they think is wrong.","ex":{"en":"We rap the manufacturers on their knuckles if the toy is shoddy","cn":"如果玩具质量低劣，我们会痛斥制造商。"}},{"pos":"PHRASE 短语","cn":"（权威人士的）指责，训斥","en":"If someone in authority gives you a rap on the knuckles, they criticize you or blame you for doing something they think is wrong.","ex":{"en":"The remark earned him a rap on the knuckles","cn":"那番话使他受到了指责。"}},{"pos":"PHRASE 短语","cn":"承担责任;（尤指替人）受责备，受处罚","en":"If you take the rap, you are blamed or punished for something, especially something that is not your fault or for which other people are equally guilty.","ex":{"en":"When the client was murdered, his wife took the rap, but did she really do it?","cn":"当那名客户被谋杀后，他妻子背上了黑锅，然而真是她杀的吗？"}},{"pos":"PHRASE 短语","cn":"逃避责任（或责罚）","en":"If you beat the rap, you avoid being blamed for something wrong that you have done.","ex":{"en":"...their decision to help Minnie beat the murder rap.","cn":"他们要帮米妮逃过谋杀罪惩罚的决定"}},{"pos":"","cn":"","en":"相关词组：rap out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be blamed for something, especially something that you did not do","cn":""},{"en":"if a person, group, or organization is in the firing line , they are publicly blamed for something bad that has happened because people think they are officially responsible","cn":""},{"en":"to accept that people will blame you for something, either because it is your fault or because they think it is your fault","cn":""}]},"collocations":{"phrases":["ADV. sharply He rapped sharply on the door. | gently","PREP. on, with rapping on the window with his stick"]},"media":{"uk":"media/ldoce/hwd/bre/1/rap_v0205.mp3","us":"media/ldoce/hwd/ame/f/rap1.mp3"},"examples":[{"en":"Wolves get a bad rap , says a woman who owns three. “","cn":"狼的名声不好，这是不公正的。”一名养着三只狼的女人说。"},{"en":"He denounced the criticisms as ‘just one bum rap after another.’","cn":"他谴责这样的批评“只不过是一次又一次的横加指斥”。"}],"oxford":{"phon":"ræp","pos":"noun","senses":[{"en":"a quick, sharp hit or knock","cn":"叩击；快速的敲击","g":"[countable]","ex":{"en":"There was a sharp rap on the door.","cn":"有人在重重地急促敲门。"}},{"en":"a type of popular music with a fast strong rhythm and words which are spoken fast, not sung","cn":"说唱音乐（节奏快而强、歌词快速念出的流行音乐）","g":"[uncountable]","ex":{"en":"a rap song/artist","cn":"说唱歌曲／艺术家"}},{"en":"a rap song","cn":"说唱歌曲","g":"[countable]"},{"en":"a criminal conviction (= the fact of being found guilty of a crime)","cn":"有罪判决；罪名；判刑","g":"[countable]","lab":"North American English, informal，，"},{"en":"an unfair judgement on something or somebody","cn":"不公正的判决；苛评","g":"[singular]","lab":"North American English, informal，，","ex":{"en":"He denounced the criticisms as ‘just one bum rap after another.’","cn":"他谴责这样的批评“只不过是一次又一次的横加指斥”。"}},{"en":"to hit a hard object or surface several times quickly, making a noise","cn":"敲击；击打","g":"[intransitive, transitive]","ex":{"en":"She rapped angrily on the door.","cn":"她怒气冲冲地敲着门。"},"pos":"verb"},{"en":"to say something suddenly and quickly in a loud, angry way","cn":"突然大声说出；突然厉声说出","g":"[transitive]","ex":{"en":"He walked through the store, rapping out orders to his staff.","cn":"他在商店里一边走一边对他的员工大声发号施令。"},"pos":"verb"},{"en":"to criticize somebody severely, usually publicly","cn":"（公开地）严厉批评，严加指责","g":"[transitive]","ex":{"en":"Some of the teachers were rapped for poor performance.","cn":"一些老师因为表现差劲而受到严厉批评。"},"pos":"verb"},{"en":"to say the words of a rap","cn":"（说唱歌中）念白；说唱","g":"[intransitive, transitive]","lab":"music","pos":"verb"}]}},"rat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"老鼠;耗子","en":"A rat is an animal which has a long tail and looks like a large mouse.","ex":{"en":"This was demonstrated in a laboratory experiment with rats.","cn":"在实验室用老鼠进行的实验证明了这一点。"}},{"pos":"N-COUNT 可数名词","cn":"卑劣的人；不忠实的人；小人","en":"If you call someone a rat, you mean that you are angry with them or dislike them, often because they have cheated you or betrayed you.","ex":{"en":"What did you do with the gun you took from that little rat Turner?","cn":"你是怎么处理从那个叫特纳的小叛徒手里得到的枪的？"}},{"pos":"VERB 动词","cn":"告密;出卖","en":"If someone rats on you, they tell someone in authority about things that you have done, especially bad things.","ex":{"en":"They were accused of encouraging children to rat on their parents.","cn":"他们被指控唆使儿童告发自己的父母。"}},{"pos":"VERB 动词","cn":"违约；食言","en":"If someone rats on an agreement, they do not do what they said they would do.","ex":{"en":"She claims he ratted on their divorce settlement.","cn":"她声称他违反了他们的离婚协议。"}},{"pos":"PHRASE 短语","cn":"怀疑有问题；发现不对头；有所警觉","en":"If you smell a rat, you begin to suspect or realize that something is wrong in a particular situation, for example that someone is trying to deceive you or harm you.","ex":{"en":"If I don't send a picture, he will smell a rat","cn":"如果我不寄出照片，他将有所察觉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to think that someone is probably guilty of something illegal or dishonest","cn":""},{"en":"thinking that someone might be guilty of doing something wrong or dishonest, without being sure","cn":""},{"en":"a feeling that someone is probably guilty of doing something wrong or dishonest","cn":""}]},"collocations":{"phrases":["ADJ. black, brown | laboratory | sewer | water","RAT + VERB scurry, scuttle A brown rat scurried across the road. | squeak | gnaw Rats had gnawed through the wires. | carry/spread disease","RAT + NOUN catcher The dog was a useful rat catcher in the warehouse. | droppings | poison","PHRASES rat-infested a rat-infested cellar"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasderat.mp3","us":"media/ldoce/hwd/ame/0/rat1.mp3"},"examples":[{"en":"Where I come from, you don't rat on your friends.","cn":"在我的老家，谁都不出卖朋友。"},{"en":"The government is accused of ratting on its promises to the unemployed.","cn":"政府被指责对失业者背信弃义。"}],"oxford":{"phon":"ræt","pos":"noun","senses":[{"en":"a small animal with a long tail, that looks like a large mouse, usually considered a pest (= an animal which is disliked because it destroys food or spreads disease)","cn":"老鼠；耗子","ex":{"en":"rat poison","cn":"老鼠药"}},{"en":"an unpleasant person, especially somebody who treats their partner or friends badly, for example by leaving them or cheating them","cn":"人渣；骗子","lab":"informal, disapproving，，","ex":{"en":"You mean he just walked out on her after fifteen years? What a rat!","cn":"你是说十五年后他就抛弃了她？真是一只老鼠啊！"}}]}},"rape":{"collins":{"senses":[{"pos":"VERB 动词","cn":"强奸;强暴","en":"If someone is raped, they are forced to have sex, usually by violence or threats of violence.","ex":{"en":"A young woman was brutally raped in her own home","cn":"一名年轻女子在自己家中惨遭强暴。"}},{"pos":"N-VAR 可变名词","cn":"强奸罪","en":"Rape is the crime of forcing someone to have sex.","ex":{"en":"Her party opposes abortion, except in cases of rape or incest","cn":"她的党派反对堕胎，但强奸或乱伦引起的怀孕除外。"}},{"pos":"N-SING 单数名词","cn":"破坏;损坏","en":"The rape of an area or of a country is the destruction or spoiling of it.","ex":{"en":"As a result of the rape of the forests, parts of the country are now short of water.","cn":"由于森林遭到破坏，目前该国的部分地区水源短缺。"}},{"pos":"","cn":"芸苔;油菜","en":"Rape is a plant with yellow flowers which is grown as a crop. Its seeds are crushed to make cooking oil."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to force someone to have sex when they do not want to","cn":""},{"en":"the crime of forcing someone to have sex when they do not want to","cn":""},{"en":"to harm a child by forcing them to have sex or touching them in a sexual way, especially over a long period of time","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Rape is a word for sexual assault — usually a man rapes a woman. This is one of the worst crimes there is. Rape can also mean to plunder or strip something of resources."}]},"collocations":{"phrases":["ADJ. alleged | attempted | marital | date, gang","RAPE + NOUN victim • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasderape.mp3","us":"media/ldoce/hwd/ame/4/rape1.mp3"},"examples":[{"en":"an increase in the number of reported rapes","cn":"强奸案报案数字的增加"},{"en":"He was charged with rape.","cn":"他被控犯了强奸罪。"}],"oxford":{"phon":"reɪp","pos":"noun","senses":[{"en":"the crime of forcing somebody to have sex when they do not want it or are not able to agree to it","cn":"强奸罪；强奸案","g":"[uncountable, countable]","ex":{"en":"He was charged with rape.","cn":"他被控犯了强奸罪。"}},{"en":"the act of destroying an area or damaging its beauty in a way that seems unnecessary","cn":"肆意损坏；糟蹋；蹂躏","g":"[singular]","lab":"literary"},{"en":"a plant with bright yellow flowers, grown as food for farm animals and for its seeds that are used to make oil","cn":"油菜","g":"[uncountable]","ex":{"en":"a field of rape","cn":"一块油菜田"}},{"en":"to force somebody to have sex when they do not want it or are not able to agree to it","cn":"强奸；强暴","ex":{"en":"She was attacked and raped.","cn":"她遭到袭击和强奸。"},"pos":"verb"}]}},"rash":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻率的；鲁莽的；冲动的","en":"If someone is rash or does rash things, they act without thinking carefully first, and therefore make mistakes or behave foolishly.","ex":{"en":"It would be rash to rely on such evidence","cn":"依靠这样的证据是草率的。"}},{"pos":"N-COUNT 可数名词","cn":"疹子;皮疹","en":"A rash is an area of red spots that appears on your skin when you are ill or have a bad reaction to something that you have eaten or touched.","ex":{"en":"I noticed a rash on my leg","cn":"我发现我腿上长了疹子。"}},{"pos":"N-SING 单数名词","cn":"大量，许多（令人不快的事情）","en":"If you talk about a rash of events or things, you mean a large number of unpleasant events or undesirable things, which have happened or appeared within a short period of time.","ex":{"en":"They believe this confusion is responsible for a rash of suicides this spring.","cn":"他们认为今年春天一连串的自杀事件是由这次混乱引起的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you do something rash , you do not think carefully about the effect it will have, and you wish later you had not done it","cn":""},{"en":"too quick to do or say something, without taking time to think about it first","cn":""},{"en":"doing things as soon as you think of them, without considering the possible dangers or problems","cn":""}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"A rash is something that spreads like wild fire — red itchy skin or a series of unfortunate events. It can also describe an impulsive, wild decision."}]},"collocations":{"phrases":["ADJ. skin | itchy | allergic | heat, nappy, nettle","VERB + RASH have | break out in, come out in When I'm stressed I break out in a rash.","RASH + VERB appear, come out, spread The rash most commonly appears on the back.","PREP. ~ on He's got a slight rash on his chest."]},"media":{"uk":"media/ldoce/hwd/bre/5/rash_las2_br.mp3","us":"media/ldoce/hwd/ame/4/rash1.mp3"},"examples":[{"en":"It would be rash to assume that everyone will agree with you on this.","cn":"你要是认为在这件事上谁都会同意你的看法，那就太欠考虑了。"},{"en":"There has been a rash of burglaries in the area over the last month.","cn":"近一个月这一带发生了很多起入室行窃案。"}],"oxford":{"phon":"ræʃ","pos":"noun","senses":[{"en":"an area of red spots on a person’s skin, caused by an illness or a reaction to something","cn":"皮疹；疹","g":"[countable, usually singular]","ex":{"en":"I woke up covered in a rash.","cn":"我醒来时长了一身皮疹。"}},{"en":"a lot of something; a series of unpleasant things that happen over a short period of time","cn":"大量；许多；（涌现的）众多令人不快的事物","g":"[singular]","ex":{"en":"a rash of movies about life in prison","cn":"大量关于监狱生活的电影"}},{"en":"doing something that may not be sensible without first thinking about the possible results; done in this way","cn":"轻率的；鲁莽的","ex":{"en":"a rash young man","cn":"鲁莽的年轻人"},"pos":"adjective"}]}},"ramble":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(在乡间的）漫游，闲逛","en":"A ramble is a long walk in the countryside.","ex":{"en":"...an hour's ramble through the woods.","cn":"一个小时的林间漫步"}},{"pos":"VERB 动词","cn":"（在乡间）漫游，闲逛","en":"If you ramble, you go on a long walk in the countryside.","ex":{"en":"...freedom to ramble across the moors.","cn":"在荒野里漫步的自由"}},{"pos":"VERB 动词","cn":"漫谈；漫笔","en":"If you say that a person rambles in their speech or writing, you mean they do not make much sense because they keep going off the subject in a confused way.","ex":{"en":"Sometimes she spoke sensibly; sometimes she rambled","cn":"有时她讲话很有条理，有时则讲得漫无边际。"}},{"pos":"","cn":"","en":"相关词组：ramble on"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move away from the main subject that you have been talking or writing about, especially for a short time during a speech or story","cn":""},{"en":"if you are talking about something and are sidetracked or get sidetracked , you allow yourself to start talking or thinking about something else, especially something less important","cn":""},{"en":"if you stray from the subject you are talking about, you start talking about other things instead, for example, because you cannot keep your attention on the main subject","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"You ramble when your talking or your walking goes on and on and on. And on. You’re in no hurry to make a point or get to your destination — if there is one at all."}]},"collocations":{"phrases":["ADJ. country, nature","VERB + RAMBLE go for/on We went for a ramble over the moors.","PREP. on a ~ The family made the amazing find while on a nature ramble in the woods."]},"media":{"uk":"media/ldoce/hwd/bre/0/ramble_n0205.mp3","us":"media/ldoce/hwd/ame/0/ramble1.mp3"},"examples":[{"en":"He had lost track of what he was saying and began to ramble.","cn":"他忘了原先的话题，开始瞎扯起来。"},{"en":"Climbing plants rambled over the front of the house.","cn":"攀缘植物贴着房子正面的墙到处长。"}],"oxford":{"phon":"ˈræmbl","pos":"verb","senses":[{"en":"to walk for pleasure, especially in the countryside","cn":"漫游，漫步，闲逛（尤指在乡间）","g":"[intransitive]","lab":"especially British English","ex":{"en":"We spent the summer rambling in Ireland.","cn":"我们花了一个夏天漫游爱尔兰。"}},{"en":"to talk about somebody/something in a confused way, especially for a long time","cn":"漫谈；闲聊；东拉西扯","g":"[intransitive]","ex":{"en":"He had lost track of what he was saying and began to ramble.","cn":"他忘了自己的话题，开始瞎扯起来。"}},{"en":"to grow in many different directions, especially over other plants or objects","cn":"蔓生；攀附生长","g":"[intransitive]","ex":{"en":"Climbing plants rambled over the front of the house.","cn":"攀缘植物贴着房子正面的墙到处疯长。"}},{"en":"a long walk for pleasure","cn":"漫步；散步","lab":"especially British English","ex":{"en":"to go for a ramble in the country","cn":"去乡间散步"},"pos":"noun"},{"en":"a long confused speech or piece of writing","cn":"杂乱无章的长篇大论","ex":{"en":"She went into a long ramble about the evils of television.","cn":"她开始东拉西扯地大谈电视的弊端。"},"pos":"noun"}]}}});
